import type { CommandResult } from "../shared/result.js";
import type { BorrowRuntime } from "./types.js";
export declare function executeBorrowTransaction(runtime: BorrowRuntime, amount: string): Promise<CommandResult>;

import { Decimal } from "@lista-dao/moolah-sdk-core";
import { executeSteps } from "../../executor.js";
import { mapMarketUserPosition } from "../../utils/position.js";
import { parsePositiveUnits } from "../../utils/validators.js";
import { buildMarketPositionPayload } from "../shared/market.js";
import { buildExecutionFailureOutput, buildPendingExecutionOutput, ensureStepsGenerated, } from "../shared/tx.js";
export async function executeBorrowTransaction(runtime, amount) {
    const { marketId, chain, chainId, walletAddress, walletTopic, marketInfo, userData, } = runtime;
    const loanInfo = marketInfo.loanInfo;
    const assets = parsePositiveUnits(amount, loanInfo.decimals, "amount");
    const requestedAmount = new Decimal(assets, loanInfo.decimals);
    if (userData.loanable.lt(requestedAmount)) {
        return {
            exitCode: 1,
            payload: {
                status: "error",
                reason: "insufficient_collateral",
                message: `Cannot borrow ${amount} ${loanInfo.symbol}. Max borrowable: ${userData.loanable.toFixed(4)} ${loanInfo.symbol}`,
                maxBorrowable: userData.loanable.toFixed(8),
                hint: "Supply more collateral or reduce borrow amount",
            },
        };
    }
    const steps = ensureStepsGenerated(await runtime.sdk.buildBorrowParams({
        chainId,
        marketId,
        assets,
        walletAddress,
        marketInfo,
    }));
    const results = await executeSteps(steps, {
        topic: walletTopic,
        chain,
    });
    const lastResult = results[results.length - 1];
    if (lastResult.status === "pending") {
        return {
            exitCode: 0,
            payload: buildPendingExecutionOutput(lastResult, results, steps.length),
        };
    }
    if (lastResult.status === "sent") {
        const newUserData = await runtime.sdk.getMarketUserData(chainId, marketId, walletAddress);
        const mappedPosition = mapMarketUserPosition(newUserData, {
            collateralPrice: 0,
            loanPrice: 0,
        });
        return {
            exitCode: 0,
            payload: {
                status: "success",
                market: marketId,
                chain,
                loan: loanInfo.symbol,
                borrowed: amount,
                txHash: lastResult.txHash,
                explorer: lastResult.explorer,
                position: buildMarketPositionPayload(mappedPosition, {
                    loanable: newUserData.loanable?.toFixed(8) || "0",
                }),
                warning: parseFloat(mappedPosition.health) < 1.2
                    ? "Health factor is low. Consider repaying some debt to avoid liquidation."
                    : undefined,
            },
        };
    }
    return {
        exitCode: 1,
        payload: buildExecutionFailureOutput(results, steps.length),
    };
}

import type { ParsedArgs } from "../../types.js";
import type { BorrowRuntime } from "./types.js";
export declare function buildBorrowSimulationPayload(args: ParsedArgs, runtime: BorrowRuntime): Promise<Record<string, unknown>>;

import { mapMarketUserPosition } from "../../utils/position.js";
import { parsePositiveUnits } from "../../utils/validators.js";
export async function buildBorrowSimulationPayload(args, runtime) {
    const { marketId, chain, marketInfo, marketExtraInfo, userData } = runtime;
    const currentLoanable = userData.loanable;
    const currentSafeBorrow = currentLoanable.mul(0.95).roundDown(userData.decimals.l);
    let afterSupplyLoanable = currentLoanable;
    let afterSupplyAmount;
    if (args.simulateSupply) {
        const parsedSupplyAmount = parsePositiveUnits(args.simulateSupply, userData.decimals.c, "simulate-supply");
        afterSupplyAmount = args.simulateSupply;
        const simulated = await runtime.sdk.simulateBorrowPosition({
            chainId: runtime.chainId,
            marketId,
            walletAddress: runtime.walletAddress,
            supplyAssets: parsedSupplyAmount,
            marketExtraInfo,
            userData,
        });
        afterSupplyLoanable = simulated.simulation.baseLoanable;
    }
    const safeAfterSupplyBorrow = afterSupplyLoanable
        .mul(0.95)
        .roundDown(userData.decimals.l);
    const mappedPosition = mapMarketUserPosition(userData, {
        collateralPrice: 0,
        loanPrice: 0,
    });
    return {
        status: "success",
        action: "simulate",
        market: marketId,
        chain,
        collateral: {
            symbol: marketInfo.collateralInfo.symbol,
            deposited: mappedPosition.collateral,
            walletBalance: mappedPosition.walletCollateralBalance,
        },
        loan: {
            symbol: marketInfo.loanInfo.symbol,
            borrowed: mappedPosition.borrowed,
            walletBalance: mappedPosition.walletLoanBalance,
        },
        position: {
            ltv: mappedPosition.ltv,
            lltv: mappedPosition.lltv,
            health: mappedPosition.health,
        },
        borrowable: {
            max: currentLoanable.toFixed(8),
            safe: currentSafeBorrow.toFixed(8),
            afterSupply: afterSupplyAmount
                ? {
                    supplyAmount: afterSupplyAmount,
                    maxBorrow: afterSupplyLoanable.toFixed(8),
                    safeBorrow: safeAfterSupplyBorrow.toFixed(8),
                }
                : undefined,
        },
        hint: afterSupplyLoanable.gt(0)
            ? `You can safely borrow up to ${safeAfterSupplyBorrow.toFixed(4)} ${marketInfo.loanInfo.symbol} (95% of max: ${afterSupplyLoanable.toFixed(4)})`
            : "No borrowing capacity. Supply collateral first.",
    };
}

import type { Address } from "viem";
import type { getSDK, MarketRuntimeData } from "../../sdk.js";
export interface BorrowRuntime {
    sdk: ReturnType<typeof getSDK>;
    marketId: Address;
    chain: string;
    chainId: number;
    walletAddress: Address;
    walletTopic: string | null;
    marketInfo: MarketRuntimeData["marketInfo"];
    marketExtraInfo: MarketRuntimeData["marketExtraInfo"];
