import { getSDK, getChainId, SUPPORTED_CHAINS, getMarketRuntimeData } from "../sdk.js";
import { loadContext, TargetType } from "../context.js";
import { InputValidationError } from "../utils/validators.js";
import { resolveMarketContext } from "./shared/context.js";
import { printJson, exitWithCode } from "./shared/output.js";
import { buildSdkErrorOutput } from "./shared/errors.js";
import { executeBorrowTransaction } from "./borrow/execute.js";
import { buildBorrowSimulationPayload } from "./borrow/simulate.js";
export async function cmdBorrow(args) {
    const ctx = loadContext();
    let marketId;
    try {
        if (!args.simulate && !args.amount) {
            throw new InputValidationError("--amount or --simulate required");
        }
        const { marketId: resolvedMarketId, chain, walletAddress, walletTopic, } = resolveMarketContext(args, ctx, {
            supportedChains: SUPPORTED_CHAINS,
            requireWalletTopic: !args.simulate,
        });
        marketId = resolvedMarketId;
        const chainId = getChainId(chain);
        const runtime = {
            sdk: getSDK(),
            marketId: resolvedMarketId,
            chain,
            chainId,
            walletAddress,
            walletTopic,
            ...(await getMarketRuntimeData(chainId, resolvedMarketId, walletAddress)),
        };
        if (args.simulate) {
            printJson(await buildBorrowSimulationPayload(args, runtime));
            exitWithCode(0);
        }
        const result = await executeBorrowTransaction(runtime, args.amount);
        printJson(result.payload);
        exitWithCode(result.exitCode);
    }
    catch (err) {
        if (err instanceof InputValidationError) {
            printJson({
                status: "error",
                reason: err.message,
            });
            exitWithCode(1);
        }
        const message = err.message || String(err);
        printJson(buildSdkErrorOutput(message, {
            targetType: TargetType.Market,
            targetId: marketId,
            insufficientReason: "insufficient_collateral",
            insufficientMessage: "Borrow amount exceeds available collateral capacity",
        }));
        exitWithCode(1);
    }
}

/**
 * Config command - manage RPC URLs and other settings
 */
export interface ConfigArgs {
    show?: boolean;
    setRpc?: boolean;
    clearRpc?: boolean;
    chain?: string;
    url?: string;
}
export declare function cmdConfig(args: ConfigArgs): Promise<void>;

/**
 * Config command - manage RPC URLs and other settings
 */
import { loadConfig, setRpcUrl, clearRpcUrl, getRpcUrl, DEFAULT_RPCS, SUPPORTED_CHAINS, } from "../config.js";
import { printJson } from "./shared/output.js";
export async function cmdConfig(args) {
    // Show current config
    if (args.show ||
        (!args.setRpc && !args.clearRpc)) {
        const config = loadConfig();
        const rpcStatus = {};
        for (const chain of SUPPORTED_CHAINS) {
            const customUrl = config.rpcUrls[chain];
            const defaultUrl = DEFAULT_RPCS[chain]?.[0];
            rpcStatus[chain] = {
                url: customUrl || defaultUrl || "not configured",
                source: customUrl ? "custom" : "default",
            };
        }
        printJson({
            defaultChain: config.defaultChain,
            supportedChains: SUPPORTED_CHAINS,
            rpcUrls: rpcStatus,
            configFile: "~/.agent-wallet/lending-config.json",
        });
        return;
    }
    // Set custom RPC
    if (args.setRpc) {
        if (!args.chain) {
            printJson({ status: "error", reason: "--chain required" });
            process.exit(1);
        }
        if (!args.url) {
            printJson({ status: "error", reason: "--url required" });
            process.exit(1);
        }
        try {
            setRpcUrl(args.chain, args.url);
            printJson({
                status: "success",
                action: "set_rpc",
                chain: args.chain,
                url: args.url,
            });
        }
        catch (err) {
            printJson({
                status: "error",
                reason: err.message,
            });
            process.exit(1);
        }
        return;
    }
    // Clear custom RPC (revert to default)
    if (args.clearRpc) {
        if (!args.chain) {
            printJson({ status: "error", reason: "--chain required" });
            process.exit(1);
        }
        try {
            clearRpcUrl(args.chain);
            const defaultUrl = getRpcUrl(args.chain);
            printJson({
                status: "success",
                action: "clear_rpc",
                chain: args.chain,
                revertedTo: defaultUrl,
            });
        }
        catch (err) {
            printJson({
                status: "error",
                reason: err.message,
            });
            process.exit(1);
        }
        return;
    }
}

/**
 * Vault deposit command
 * Deposits assets into a Lista Lending vault
 * After success, re-queries position on-chain
 */
import type { ParsedArgs } from "../types.js";
export declare function cmdDeposit(args: ParsedArgs): Promise<void>;

/**
 * Vault deposit command
 * Deposits assets into a Lista Lending vault
 * After success, re-queries position on-chain
 */
import { getSDK, getChainId, SUPPORTED_CHAINS } from "../sdk.js";
import { executeSteps } from "../executor.js";
import { loadContext, TargetType, updatePosition, } from "../context.js";
import { mapVaultUserPosition } from "../utils/position.js";
import { InputValidationError, parsePositiveUnits } from "../utils/validators.js";
import { resolveVaultContext, requireAmount, } from "./shared/context.js";
import { printJson, exitWithCode } from "./shared/output.js";
import { buildExecutionFailureOutput, buildPendingExecutionOutput, ensureStepsGenerated, } from "./shared/tx.js";
import { buildSdkErrorOutput } from "./shared/errors.js";
export async function cmdDeposit(args) {
    const ctx = loadContext();
    let operationContext;
    try {
        const amount = requireAmount(args.amount);
        const { vaultAddress, chain, walletAddress, walletTopic } = resolveVaultContext(args, ctx, { supportedChains: SUPPORTED_CHAINS });
        const chainId = getChainId(chain);
        const sdk = getSDK();
        operationContext = {
            vaultAddress,
            chain,
            amount,
        };
        // 1. Get vault info to determine asset decimals
        const vaultInfo = await sdk.getVaultInfo(chainId, vaultAddress);
        // 2. Parse amount with correct decimals (SDK uses assetInfo)
        const assetInfo = vaultInfo.assetInfo;
        const decimals = assetInfo.decimals;
        const assets = parsePositiveUnits(amount, decimals, "amount");
        // 3. Build deposit steps (may include approve step)
        const steps = ensureStepsGenerated(await sdk.buildVaultDepositParams({
            chainId,
            vaultAddress,
            assets,
            walletAddress,
            vaultInfo,
        }));
        // 4. Execute steps via lista-wallet-connect
        const results = await executeSteps(steps, {
            topic: walletTopic,
            chain,
        });
        // 5. Check result
        const lastResult = results[results.length - 1];
        if (lastResult.status === "pending") {
            printJson(buildPendingExecutionOutput(lastResult, results, steps.length));
            exitWithCode(0);
        }
        if (lastResult.status === "sent") {
            // 6. Re-query position on-chain after successful deposit
            // Re-fetch vault info to get fresh state after deposit
            const freshVaultInfo = await sdk.getVaultInfo(chainId, vaultAddress);
            const userData = await sdk.getVaultUserData(chainId, vaultAddress, walletAddress, freshVaultInfo);
            const mappedPosition = mapVaultUserPosition(userData);
            const newPosition = mappedPosition.position;
            // Update context if this is the selected vault
            if (ctx.selectedVault?.address === vaultAddress) {
                updatePosition(newPosition);
            }
            printJson({
                status: "success",
                vault: vaultAddress,
                chain,
                asset: assetInfo.symbol,
                deposited: amount,
                steps: results.length,
                txHash: lastResult.txHash,
                explorer: lastResult.explorer,
                balance: mappedPosition.walletBalance,
                vaultBalance: newPosition.assets,
                position: {
                    balance: newPosition.assets,
                    assets: newPosition.assets,
                    walletBalance: mappedPosition.walletBalance,
                    assetSymbol: assetInfo.symbol,
                },
            });
            exitWithCode(0);
        }
        printJson(buildExecutionFailureOutput(results, steps.length));
        exitWithCode(1);
    }
    catch (err) {
        if (err instanceof InputValidationError) {
            printJson({
                status: "error",
                reason: err.message,
            });
            exitWithCode(1);
        }
        const message = err.message || String(err);
        printJson(buildSdkErrorOutput(message, {
            targetType: TargetType.Vault,
            targetId: operationContext?.vaultAddress,
        }));
        exitWithCode(1);
    }
}

/**
 * Holdings command - query user's vault/market positions
 */
import type { HoldingsScope } from "../types/lista-api.js";
export interface HoldingsArgs {
    address?: string;
    scope?: HoldingsScope;
}
export declare function cmdHoldings(args: HoldingsArgs): Promise<void>;

/**
 * Holdings command - query user's vault/market positions
 */
import { fetchMarketPositions, fetchUserPositions, fetchVaultPositions } from "../api.js";
import { loadContext, setLastFilters } from "../context.js";
import { printJson } from "./shared/output.js";
import { isValidAddress } from "../utils/validators.js";
export async function cmdHoldings(args) {
    const ctx = loadContext();
    const address = args.address || ctx.userAddress;
    const scope = args.scope || "all";
    if (!address) {
        printJson({
            status: "error",
            reason: "--address required (or select a wallet first)",
        });
        process.exit(1);
    }
    if (!isValidAddress(address)) {
        printJson({
            status: "error",
            reason: `Invalid address: ${address}`,
        });
        process.exit(1);
    }
    if (!["all", "vault", "market", "selected"].includes(scope)) {
        printJson({
            status: "error",
            reason: "--scope must be all, vault, market, or selected",
        });
        process.exit(1);
    }
    try {
        let vaults = [];
        let markets = [];
        if (scope === "all") {
            const data = await fetchUserPositions(address);
            vaults = data.vaults;
            markets = data.markets;
        }
        else if (scope === "vault") {
            vaults = await fetchVaultPositions(address);
        }
        else if (scope === "market") {
            markets = await fetchMarketPositions(address);
        }
        else {
            if (!ctx.selectedVault && !ctx.selectedMarket) {
                printJson({
                    status: "error",
                    reason: "No selected position. Use select first or query --scope all",
                });
                process.exit(1);
            }
            const [vaultData, marketData] = await Promise.all([
                ctx.selectedVault ? fetchVaultPositions(address) : Promise.resolve([]),
                ctx.selectedMarket ? fetchMarketPositions(address) : Promise.resolve([]),
            ]);
            if (ctx.selectedVault) {
                vaults = vaultData.filter((item) => item.vaultAddress.toLowerCase() === ctx.selectedVault.address.toLowerCase() &&
                    item.chain === ctx.selectedVault.chain);
                // Fallback to cached selected position if API holdings excludes zero-amount entries.
                if (vaults.length === 0 &&
                    ctx.userPosition &&
                    ctx.userAddress &&
                    ctx.userAddress.toLowerCase() === address.toLowerCase()) {
                    vaults = [
                        {
                            kind: "vault",
                            vaultAddress: ctx.selectedVault.address,
                            vaultName: ctx.selectedVault.name,
                            curator: "N/A",
                            apy: "0",
                            chain: ctx.selectedVault.chain,
                            assetSymbol: ctx.selectedVault.asset.symbol,
                            assetPrice: "0",
                            walletBalance: "0",
                            deposited: ctx.userPosition.assets,
                            depositedUsd: ctx.userPosition.assetsUsd || "0",
                            shares: ctx.userPosition.shares,
                            hasPosition: Number.parseFloat(ctx.userPosition.assets) > 0,
                        },
                    ];
                }
            }
            if (ctx.selectedMarket) {
                markets = marketData.filter((item) => item.marketId.toLowerCase() === ctx.selectedMarket.marketId.toLowerCase() &&
                    item.chain === ctx.selectedMarket.chain);
            }
        }
        setLastFilters({
            holdings: {
                scope,
                address,
                at: new Date().toISOString(),
            },
        });
        const count = vaults.length + markets.length;
        const diagnostics = {
            vaultErrors: vaults.filter((item) => Boolean(item.error)).length,
            marketErrors: markets.filter((item) => Boolean(item.error)).length,
        };
        if (count === 0) {
            printJson({
                status: "success",
                address,
                scope,
                counts: {
                    vaults: 0,
                    markets: 0,
                    total: 0,
                },
                diagnostics,
                vaults: [],
                markets: [],
                message: "No positions found",
            });
            process.exit(0);
        }
        printJson({
            status: "success",
            address,
            scope,
            counts: {
                vaults: vaults.length,
                markets: markets.length,
                total: count,
            },
            diagnostics,
            vaults,
            markets,
        });
        process.exit(0);
    }
    catch (err) {
        printJson({
            status: "error",
            reason: "sdk_error",
            message: err.message,
        });
        process.exit(1);
    }
}

