        chainId: runtime.chainId,
        marketId,
        walletAddress: runtime.walletAddress,
        repayAssets,
        repayAll: Boolean(args.repayAll),
        marketExtraInfo,
        userData,
    });
    const simulation = simulated.simulation;
    const mappedPosition = mapMarketUserPosition(userData, {
        collateralPrice: 0,
        loanPrice: 0,
    });
    return {
        status: "success",
        action: "simulate",
        market: marketId,
        chain,
        loan: loanSymbol,
        repay: {
