import { buildBorrowSimulationPayload } from "./borrow/simulate.js";
import type { BorrowRuntime } from "./borrow/types.js";

export async function cmdBorrow(args: ParsedArgs): Promise<void> {
  const ctx = loadContext();
  let marketId: string | undefined;

  try {
    if (!args.simulate && !args.amount) {
      throw new InputValidationError("--amount or --simulate required");
    }

    const {
      marketId: resolvedMarketId,
      chain,
      walletAddress,
      walletTopic,
    } = resolveMarketContext(args, ctx, {
      supportedChains: SUPPORTED_CHAINS,
      requireWalletTopic: !args.simulate,
    });

    marketId = resolvedMarketId;
    const chainId = getChainId(chain);

    const runtime: BorrowRuntime = {
      sdk: getSDK(),
      marketId: resolvedMarketId,
      chain,
      chainId,
      walletAddress,
      walletTopic,
      ...(await getMarketRuntimeData(chainId, resolvedMarketId, walletAddress)),
    };

    if (args.simulate) {
      printJson(await buildBorrowSimulationPayload(args, runtime));
      exitWithCode(0);
    }

    const result = await executeBorrowTransaction(runtime, args.amount as string);
    printJson(result.payload);
    exitWithCode(result.exitCode);
  } catch (err) {
    if (err instanceof InputValidationError) {
      printJson({
        status: "error",
        reason: err.message,
      });
      exitWithCode(1);
    }

    const message = (err as Error).message || String(err);
    printJson(
      buildSdkErrorOutput(message, {
        targetType: TargetType.Market,
        targetId: marketId,
        insufficientReason: "insufficient_collateral",
        insufficientMessage: "Borrow amount exceeds available collateral capacity",
      })
    );
    exitWithCode(1);
  }
}

/**
 * Config command - manage RPC URLs and other settings
 */

import {
  loadConfig,
  setRpcUrl,
  clearRpcUrl,
  getRpcUrl,
  DEFAULT_RPCS,
  SUPPORTED_CHAINS,
} from "../config.js";
import { printJson } from "./shared/output.js";

export interface ConfigArgs {
  show?: boolean;
  setRpc?: boolean;
  clearRpc?: boolean;
  chain?: string;
  url?: string;
}

export async function cmdConfig(args: ConfigArgs): Promise<void> {
  // Show current config
  if (
    args.show ||
    (!args.setRpc && !args.clearRpc)
  ) {
    const config = loadConfig();

    const rpcStatus: Record<string, { url: string; source: string }> = {};

    for (const chain of SUPPORTED_CHAINS) {
      const customUrl = config.rpcUrls[chain];
      const defaultUrl = DEFAULT_RPCS[chain]?.[0];

      rpcStatus[chain] = {
        url: customUrl || defaultUrl || "not configured",
        source: customUrl ? "custom" : "default",
      };
    }

    printJson({
      defaultChain: config.defaultChain,
      supportedChains: SUPPORTED_CHAINS,
      rpcUrls: rpcStatus,
      configFile: "~/.agent-wallet/lending-config.json",
    });
    return;
  }

  // Set custom RPC
  if (args.setRpc) {
    if (!args.chain) {
      printJson({ status: "error", reason: "--chain required" });
      process.exit(1);
    }
    if (!args.url) {
      printJson({ status: "error", reason: "--url required" });
      process.exit(1);
    }

    try {
      setRpcUrl(args.chain, args.url);
      printJson({
        status: "success",
        action: "set_rpc",
        chain: args.chain,
        url: args.url,
      });
    } catch (err) {
      printJson({
        status: "error",
        reason: (err as Error).message,
      });
      process.exit(1);
    }
    return;
  }

  // Clear custom RPC (revert to default)
  if (args.clearRpc) {
    if (!args.chain) {
      printJson({ status: "error", reason: "--chain required" });
      process.exit(1);
    }

    try {
      clearRpcUrl(args.chain);
      const defaultUrl = getRpcUrl(args.chain);
      printJson({
        status: "success",
        action: "clear_rpc",
        chain: args.chain,
        revertedTo: defaultUrl,
      });
    } catch (err) {
      printJson({
        status: "error",
        reason: (err as Error).message,
      });
      process.exit(1);
    }
    return;
  }
}

/**
 * Vault deposit command
 * Deposits assets into a Lista Lending vault
 * After success, re-queries position on-chain
 */

import type { ParsedArgs, StepParam } from "../types.js";
import { getSDK, getChainId, SUPPORTED_CHAINS } from "../sdk.js";
import { executeSteps } from "../executor.js";
import {
  loadContext,
  TargetType,
  updatePosition,
  type UserPosition,
} from "../context.js";
import { mapVaultUserPosition } from "../utils/position.js";
import { InputValidationError, parsePositiveUnits } from "../utils/validators.js";
import {
  resolveVaultContext,
  requireAmount,
} from "./shared/context.js";
import { printJson, exitWithCode } from "./shared/output.js";
import {
  buildExecutionFailureOutput,
  buildPendingExecutionOutput,
  ensureStepsGenerated,
} from "./shared/tx.js";
import { buildSdkErrorOutput } from "./shared/errors.js";

export async function cmdDeposit(args: ParsedArgs): Promise<void> {
  const ctx = loadContext();
  let operationContext:
    | {
        vaultAddress: string;
        chain: string;
        amount: string;
      }
    | undefined;

  try {
    const amount = requireAmount(args.amount);
    const { vaultAddress, chain, walletAddress, walletTopic } = resolveVaultContext(
      args,
      ctx,
      { supportedChains: SUPPORTED_CHAINS }
    );
    const chainId = getChainId(chain);
    const sdk = getSDK();
    operationContext = {
      vaultAddress,
      chain,
      amount,
    };

    // 1. Get vault info to determine asset decimals
    const vaultInfo = await sdk.getVaultInfo(chainId, vaultAddress);

    // 2. Parse amount with correct decimals (SDK uses assetInfo)
    const assetInfo = vaultInfo.assetInfo;
    const decimals = assetInfo.decimals;
    const assets = parsePositiveUnits(amount, decimals, "amount");
    // 3. Build deposit steps (may include approve step)
    const steps = ensureStepsGenerated(
      await sdk.buildVaultDepositParams({
        chainId,
        vaultAddress,
        assets,
        walletAddress,
        vaultInfo,
      })
    );

    // 4. Execute steps via lista-wallet-connect
    const results = await executeSteps(steps, {
      topic: walletTopic!,
      chain,
    });

    // 5. Check result
    const lastResult = results[results.length - 1];

    if (lastResult.status === "pending") {
      printJson(buildPendingExecutionOutput(lastResult, results, steps.length));
      exitWithCode(0);
    }

    if (lastResult.status === "sent") {
      // 6. Re-query position on-chain after successful deposit
      // Re-fetch vault info to get fresh state after deposit
      const freshVaultInfo = await sdk.getVaultInfo(chainId, vaultAddress);
      const userData = await sdk.getVaultUserData(
        chainId,
        vaultAddress,
        walletAddress,
        freshVaultInfo
      );

      const mappedPosition = mapVaultUserPosition(userData);

      const newPosition: UserPosition = mappedPosition.position;

      // Update context if this is the selected vault
      if (ctx.selectedVault?.address === vaultAddress) {
        updatePosition(newPosition);
      }

      printJson({
        status: "success",
        vault: vaultAddress,
        chain,
        asset: assetInfo.symbol,
        deposited: amount,
        steps: results.length,
        txHash: lastResult.txHash,
        explorer: lastResult.explorer,
        balance: mappedPosition.walletBalance,
        vaultBalance: newPosition.assets,
        position: {
          balance: newPosition.assets,
          assets: newPosition.assets,
          walletBalance: mappedPosition.walletBalance,
          assetSymbol: assetInfo.symbol,
        },
      });
      exitWithCode(0);
    }

    printJson(buildExecutionFailureOutput(results, steps.length));
    exitWithCode(1);
  } catch (err) {
    if (err instanceof InputValidationError) {
      printJson({
        status: "error",
        reason: err.message,
      });
      exitWithCode(1);
    }

    const message = (err as Error).message || String(err);

    printJson(
      buildSdkErrorOutput(message, {
        targetType: TargetType.Vault,
        targetId: operationContext?.vaultAddress,
      })
    );
    exitWithCode(1);
  }
}

/**
 * Holdings command - query user's vault/market positions
 */

import { fetchMarketPositions, fetchUserPositions, fetchVaultPositions } from "../api.js";
import { loadContext, setLastFilters } from "../context.js";
import { printJson } from "./shared/output.js";
import type { HoldingsScope } from "../types/lista-api.js";
import { isValidAddress } from "../utils/validators.js";

export interface HoldingsArgs {
  address?: string;
  scope?: HoldingsScope;
}

export async function cmdHoldings(args: HoldingsArgs): Promise<void> {
  const ctx = loadContext();
  const address = args.address || ctx.userAddress;
  const scope = args.scope || "all";

  if (!address) {
    printJson({
      status: "error",
      reason: "--address required (or select a wallet first)",
    });
    process.exit(1);
  }

  if (!isValidAddress(address)) {
    printJson({
      status: "error",
      reason: `Invalid address: ${address}`,
    });
    process.exit(1);
  }

  if (!["all", "vault", "market", "selected"].includes(scope)) {
    printJson({
      status: "error",
      reason: "--scope must be all, vault, market, or selected",
    });
    process.exit(1);
  }

  try {
    let vaults = [] as Awaited<ReturnType<typeof fetchVaultPositions>>;
    let markets = [] as Awaited<ReturnType<typeof fetchMarketPositions>>;

    if (scope === "all") {
      const data = await fetchUserPositions(address);
      vaults = data.vaults;
      markets = data.markets;
    } else if (scope === "vault") {
      vaults = await fetchVaultPositions(address);
    } else if (scope === "market") {
      markets = await fetchMarketPositions(address);
    } else {
      if (!ctx.selectedVault && !ctx.selectedMarket) {
        printJson({
          status: "error",
          reason: "No selected position. Use select first or query --scope all",
        });
        process.exit(1);
      }

      const [vaultData, marketData] = await Promise.all([
        ctx.selectedVault ? fetchVaultPositions(address) : Promise.resolve([]),
        ctx.selectedMarket ? fetchMarketPositions(address) : Promise.resolve([]),
      ]);

      if (ctx.selectedVault) {
        vaults = vaultData.filter(
          (item) =>
            item.vaultAddress.toLowerCase() === ctx.selectedVault!.address.toLowerCase() &&
            item.chain === ctx.selectedVault!.chain
        );

        // Fallback to cached selected position if API holdings excludes zero-amount entries.
        if (
          vaults.length === 0 &&
          ctx.userPosition &&
          ctx.userAddress &&
          ctx.userAddress.toLowerCase() === address.toLowerCase()
        ) {
          vaults = [
            {
              kind: "vault",
              vaultAddress: ctx.selectedVault.address,
              vaultName: ctx.selectedVault.name,
              curator: "N/A",
              apy: "0",
              chain: ctx.selectedVault.chain,
              assetSymbol: ctx.selectedVault.asset.symbol,
              assetPrice: "0",
              walletBalance: "0",
              deposited: ctx.userPosition.assets,
              depositedUsd: ctx.userPosition.assetsUsd || "0",
              shares: ctx.userPosition.shares,
              hasPosition: Number.parseFloat(ctx.userPosition.assets) > 0,
            },
          ];
        }
      }

      if (ctx.selectedMarket) {
        markets = marketData.filter(
          (item) =>
            item.marketId.toLowerCase() === ctx.selectedMarket!.marketId.toLowerCase() &&
            item.chain === ctx.selectedMarket!.chain
        );
      }
    }

    setLastFilters({
      holdings: {
        scope,
        address,
        at: new Date().toISOString(),
      },
    });

    const count = vaults.length + markets.length;
    const diagnostics = {
      vaultErrors: vaults.filter((item) => Boolean(item.error)).length,
      marketErrors: markets.filter((item) => Boolean(item.error)).length,
    };

    if (count === 0) {
      printJson({
        status: "success",
        address,
        scope,
        counts: {
          vaults: 0,
          markets: 0,
          total: 0,
        },
        diagnostics,
        vaults: [],
        markets: [],
        message: "No positions found",
      });
      process.exit(0);
    }

    printJson({
      status: "success",
      address,
      scope,
      counts: {
        vaults: vaults.length,
        markets: markets.length,
        total: count,
      },
      diagnostics,
      vaults,
      markets,
    });
    process.exit(0);
  } catch (err) {
    printJson({
      status: "error",
      reason: "sdk_error",
      message: (err as Error).message,
    });
    process.exit(1);
  }
}

/**
 * Market withdraw command
 * Withdraw collateral from a Lista Lending market
 *
 * Features:
 * - --amount: Withdraw specific amount
 * - --withdraw-all: Withdraw all collateral (only if no debt)
 */

import { Decimal } from "@lista-dao/moolah-sdk-core";
import {
  getSDK,
  getChainId,
  SUPPORTED_CHAINS,
  getMarketRuntimeData,
} from "../sdk.js";
import { executeSteps } from "../executor.js";
import {
  loadContext,
  TargetType,
} from "../context.js";
import type { ParsedArgs } from "../types.js";
import { mapMarketUserPosition } from "../utils/position.js";
import { InputValidationError, parsePositiveUnits } from "../utils/validators.js";
import {
  requireAmountOrAll,
  resolveMarketContext,
} from "./shared/context.js";
import { printJson, exitWithCode } from "./shared/output.js";
import {
  buildExecutionFailureOutput,
  buildPendingExecutionOutput,
  ensureStepsGenerated,
} from "./shared/tx.js";
import { buildSdkErrorOutput } from "./shared/errors.js";
import {
  buildMarketPositionPayload,
  getExceedsWithdrawableError,
  getWithdrawAllHasDebtError,
  getWithdrawNoCollateralError,
} from "./shared/market.js";

export async function cmdMarketWithdraw(args: ParsedArgs): Promise<void> {
  const ctx = loadContext();
  let operationContext:
    | {
        marketId: string;
        chain: string;
        amount: string;
      }
    | undefined;

  try {
    requireAmountOrAll(args.amount, args.withdrawAll, "--withdraw-all");
    const { marketId, chain, walletAddress, walletTopic } = resolveMarketContext(
      args,
      ctx,
      { supportedChains: SUPPORTED_CHAINS }
    );
    const chainId = getChainId(chain);
    const sdk = getSDK();

    // 1. Get market info and user data
    const { marketInfo, userData } = await getMarketRuntimeData(
      chainId,
      marketId,
      walletAddress
    );
    const collateralInfo = marketInfo.collateralInfo;

    // Check if user has collateral to withdraw
    if (userData.collateral.isZero()) {
      printJson(getWithdrawNoCollateralError());
      exitWithCode(1);
    }

    // Check if user can withdraw all (only if no debt)
    if (args.withdrawAll && !userData.borrowed.isZero()) {
      printJson(getWithdrawAllHasDebtError(userData));
      exitWithCode(1);
    }

    // 2. Parse amount (if not withdraw-all)
    const decimals = collateralInfo.decimals;
    let assets: bigint | undefined;
    if (args.amount) {
      assets = parsePositiveUnits(args.amount, decimals, "amount");
      const requestedWithdrawAmount = new Decimal(assets, decimals);

      // Check if withdraw amount exceeds withdrawable
      if (userData.withdrawable.lt(requestedWithdrawAmount)) {
        printJson(
          getExceedsWithdrawableError(args.amount, userData, collateralInfo.symbol)
        );
        exitWithCode(1);
      }
    }

    const operationAmount = args.amount || "all";
    operationContext = {
      marketId,
      chain,
      amount: operationAmount,
    };

    // 3. Build withdraw steps
    const steps = ensureStepsGenerated(
      await sdk.buildWithdrawParams({
        chainId,
        marketId,
        assets,
        withdrawAll: args.withdrawAll,
        walletAddress,
        marketInfo,
        userData,
      })
    );

    // 4. Execute steps via lista-wallet-connect
    const results = await executeSteps(steps, {
      topic: walletTopic!,
      chain,
    });

    // 5. Check result
    const lastResult = results[results.length - 1];

    if (lastResult.status === "pending") {
      printJson(buildPendingExecutionOutput(lastResult, results, steps.length));
      exitWithCode(0);
    }

    if (lastResult.status === "sent") {
      // 6. Re-query position on-chain after successful withdraw
      const newUserData = await sdk.getMarketUserData(chainId, marketId, walletAddress);
      const mappedPosition = mapMarketUserPosition(newUserData, {
        collateralPrice: 0,
        loanPrice: 0,
      });

      printJson({
        status: "success",
        market: marketId,
        chain,
        collateral: collateralInfo.symbol,
        withdrawn: operationAmount,
        txHash: lastResult.txHash,
        explorer: lastResult.explorer,
        position: buildMarketPositionPayload(mappedPosition, {
          withdrawable: newUserData.withdrawable?.toFixed(8) || "0",
          remainingCollateral: mappedPosition.collateral !== "0",
        }),
      });
      exitWithCode(0);
    }

    printJson(buildExecutionFailureOutput(results, steps.length));
    exitWithCode(1);
  } catch (err) {
    if (err instanceof InputValidationError) {
      printJson({
        status: "error",
        reason: err.message,
      });
      exitWithCode(1);
    }

    const message = (err as Error).message || String(err);

    printJson(
      buildSdkErrorOutput(message, {
        targetType: TargetType.Market,
        targetId: operationContext?.marketId,
        insufficientReason: "exceeds_withdrawable",
        insufficientMessage: "Withdraw amount exceeds available withdrawable collateral",
      })
    );
    exitWithCode(1);
  }
}

/**
 * Markets command - list available markets
 * Excludes SmartLending (zone=3) and Fixed-term (termType=1) markets
 */

import { fetchMarkets } from "../api.js";
import { SUPPORTED_CHAINS } from "../config.js";
import { setLastFilters } from "../context.js";
import { printJson } from "./shared/output.js";
import type { ListOrder } from "../types/lista-api.js";
import {
  isPositiveInteger,
  isSupportedChain,
  isValidOrder,
} from "../utils/validators.js";

// Zone constants
const ZONE_SMART_LENDING = 3;
// TermType constants
const TERM_TYPE_FIXED = 1;
const MARKET_OPERATION_LIMITATION_NOTE =
  "Smart Lending and fixed-term market operations are currently not supported in this skill. For full functionality, please use the Lista website.";

function formatUsd(value: string): string {
  const num = Number.parseFloat(value);
  if (!Number.isFinite(num)) return "0";
  if (num >= 1_000_000) return `${(num / 1_000_000).toFixed(2)}M`;
  if (num >= 1_000) return `${(num / 1_000).toFixed(2)}K`;
  return num.toFixed(2);
}

export interface MarketsArgs {
  chain?: string;
  page?: number;
  pageSize?: number;
  sort?: string;
  order?: ListOrder;
  zone?: string | number;
  keyword?: string;
  loans?: string[];
  collaterals?: string[];
}

export async function cmdMarkets(args: MarketsArgs): Promise<void> {
  const chain = args.chain || "eip155:56";

  if (!isSupportedChain(chain, SUPPORTED_CHAINS)) {
    printJson({
      status: "error",
      reason: `Unsupported chain: ${chain}. Supported: ${SUPPORTED_CHAINS.join(", ")}`,
    });
    process.exit(1);
  }

  if (args.page !== undefined && !isPositiveInteger(args.page)) {
    printJson({
      status: "error",
      reason: "--page must be a positive integer",
    });
    process.exit(1);
  }

  if (args.pageSize !== undefined && !isPositiveInteger(args.pageSize)) {
    printJson({
      status: "error",
      reason: "--page-size must be a positive integer",
    });
    process.exit(1);
  }

  if (args.order && !isValidOrder(args.order)) {
    printJson({
      status: "error",
      reason: "--order must be asc or desc",
    });
    process.exit(1);
  }

  try {
    // Fetch markets - exclude SmartLending (zone=3) and Fixed-term (termType=1)
    // We filter client-side after fetching to ensure compatibility
    const markets = await fetchMarkets({
      chain,
      page: args.page,
      pageSize: args.pageSize,
      sort: args.sort,
      order: args.order,
      zone: args.zone,
      keyword: args.keyword,
      loans: args.loans,
      collaterals: args.collaterals,
    });

    // Additional client-side filter as safety net
    const filteredMarkets = markets.filter(
      (m) => m.zone !== ZONE_SMART_LENDING && m.termType !== TERM_TYPE_FIXED
    );

    setLastFilters({
      markets: {
        chain,
        page: args.page || 1,
        pageSize: args.pageSize || 100,
        sort: args.sort,
        order: args.order,
        zone: args.zone,
        keyword: args.keyword,
        loans: args.loans,
        collaterals: args.collaterals,
        at: new Date().toISOString(),
      },
    });

    if (filteredMarkets.length === 0) {
      printJson({
        status: "success",
        chain,
        markets: [],
        message: "No markets found",
        note: MARKET_OPERATION_LIMITATION_NOTE,
      });
      return;
    }

    // Output JSON for agent parsing
    printJson({
      status: "success",
      chain,
      count: filteredMarkets.length,
      filters: {
        page: args.page || 1,
        pageSize: args.pageSize || 100,
        sort: args.sort,
        order: args.order,
        zone: args.zone,
        keyword: args.keyword,
        loans: args.loans,
        collaterals: args.collaterals,
      },
      note: MARKET_OPERATION_LIMITATION_NOTE,
      markets: filteredMarkets.map((m, i) => ({
        index: i,
        marketId: m.id,
        collateralSymbol: m.collateral,
        loanSymbol: m.loan,
        zone: m.zone,
        termType: m.termType,
        lltv: m.lltv,
        supplyApy: m.supplyApy,
        borrowRate: m.rate,
        liquidity: m.liquidity,
        liquidityUsd: m.liquidityUsd,
        vaults: m.vaults?.map((v: { name: string }) => v.name).join(", "),
        display: `[${i}] ${m.collateral}/${m.loan} - LLTV: ${(Number.parseFloat(m.lltv) * 100).toFixed(1)}%, Liquidity: $${formatUsd(m.liquidityUsd)}`,
      })),
    });
  } catch (err) {
    printJson({
      status: "error",
      reason: "sdk_error",
      message: (err as Error).message,
    });
    process.exit(1);
  }
}

import { executeSteps } from "../../executor.js";
import type { ParsedArgs } from "../../types.js";
import { mapMarketUserPosition } from "../../utils/position.js";
import { parsePositiveUnits } from "../../utils/validators.js";
import {
  buildMarketPositionPayload,
  buildRepayHint,
} from "../shared/market.js";
import type { CommandResult } from "../shared/result.js";
import {
  buildExecutionFailureOutput,
  buildPendingExecutionOutput,
  ensureStepsGenerated,
} from "../shared/tx.js";
import type { RepayRuntime } from "./types.js";

export async function executeRepayTransaction(
  runtime: RepayRuntime,
  args: Pick<ParsedArgs, "amount" | "repayAll">
): Promise<CommandResult> {
  const { marketId, chain, chainId, walletAddress, walletTopic, marketInfo, userData } =
    runtime;

  let assets: bigint | undefined;
  if (args.amount) {
    assets = parsePositiveUnits(args.amount, marketInfo.loanInfo.decimals, "amount");
  }

  const steps = ensureStepsGenerated(
    await runtime.sdk.buildRepayParams({
      chainId,
      marketId,
      assets,
      repayAll: args.repayAll,
      walletAddress,
      marketInfo,
      userData,
    })
  );

  const results = await executeSteps(steps, {
    topic: walletTopic!,
    chain,
  });
  const lastResult = results[results.length - 1];

  if (lastResult.status === "pending") {
    return {
      exitCode: 0,
      payload: buildPendingExecutionOutput(lastResult, results, steps.length),
    };
  }

  if (lastResult.status === "sent") {
    const newUserData = await runtime.sdk.getMarketUserData(
      chainId,
      marketId,
      walletAddress
    );
    const mappedPosition = mapMarketUserPosition(newUserData, {
      collateralPrice: 0,
      loanPrice: 0,
    });

    return {
      exitCode: 0,
      payload: {
        status: "success",
        market: marketId,
        chain,
        loan: marketInfo.loanInfo.symbol,
        repaid: args.amount || "all",
        txHash: lastResult.txHash,
        explorer: lastResult.explorer,
        position: buildMarketPositionPayload(mappedPosition, {
          withdrawable: newUserData.withdrawable?.toFixed(8) || "0",
          remainingDebt: mappedPosition.borrowed !== "0",
        }),
        hint: buildRepayHint(newUserData),
      },
    };
  }

  return {
    exitCode: 1,
    payload: buildExecutionFailureOutput(results, steps.length),
  };
}

import { Decimal } from "@lista-dao/moolah-sdk-core";
import type { ParsedArgs } from "../../types.js";
import { mapMarketUserPosition } from "../../utils/position.js";
import { InputValidationError, parsePositiveUnits } from "../../utils/validators.js";
import type { RepayRuntime } from "./types.js";

export async function buildRepaySimulationPayload(
  args: ParsedArgs,
  runtime: RepayRuntime
): Promise<Record<string, unknown>> {
  const { marketId, chain, marketExtraInfo, userData, marketInfo } = runtime;
  const loanSymbol = marketInfo.loanInfo.symbol;

  let repayAssets = 0n;
  let estimatedRepay = "0";
  if (args.repayAll) {
    repayAssets = userData.borrowed.roundDown(userData.decimals.l).numerator;
    estimatedRepay = userData.borrowed.toFixed(8);
  } else if (args.amount) {
    const parsedAmount = parsePositiveUnits(args.amount, userData.decimals.l, "amount");
    if (userData.borrowed.lt(new Decimal(parsedAmount, userData.decimals.l))) {
      throw new InputValidationError(
        `Repay amount exceeds current debt (${userData.borrowed.toFixed(8)} ${loanSymbol})`
      );
    }
    repayAssets = parsedAmount;
    estimatedRepay = args.amount;
  }

  const simulated = await runtime.sdk.simulateRepayPosition({
    chainId: runtime.chainId,
    marketId,
    walletAddress: runtime.walletAddress,
    repayAssets,
    repayAll: Boolean(args.repayAll),
    marketExtraInfo,
    userData,
  });
  const simulation = simulated.simulation;

  const mappedPosition = mapMarketUserPosition(userData, {
    collateralPrice: 0,
    loanPrice: 0,
  });

  return {
    status: "success",
    action: "simulate",
    market: marketId,
    chain,
    loan: loanSymbol,
    repay: {
      amount: args.repayAll ? "all" : args.amount,
      repayAll: Boolean(args.repayAll),
      currentDebt: userData.borrowed.toFixed(8),
      estimatedRepay,
    },
    current: {
      borrowed: mappedPosition.borrowed,
      ltv: mappedPosition.ltv,
      withdrawable: userData.withdrawable.toFixed(8),
      health: mappedPosition.health,
    },
    afterRepay: {
      borrowed: simulation.borrowed.toFixed(8),
      ltv: simulation.LTV.toFixed(8),
      withdrawable: simulation.withdrawable.toFixed(8),
    },
    hint: simulation.borrowed.isZero()
      ? "Repay will fully clear debt."
      : `Estimated remaining debt: ${simulation.borrowed.toFixed(8)} ${loanSymbol}`,
  };
}

import type { Address } from "viem";
import type { getSDK, MarketRuntimeData } from "../../sdk.js";

export interface RepayRuntime {
  sdk: ReturnType<typeof getSDK>;
  marketId: Address;
  chain: string;
  chainId: number;
  walletAddress: Address;
  walletTopic: string | null;
  marketInfo: MarketRuntimeData["marketInfo"];
  marketExtraInfo: MarketRuntimeData["marketExtraInfo"];
  userData: MarketRuntimeData["userData"];
}

import { getSDK, getChainId, SUPPORTED_CHAINS, getMarketRuntimeData } from "../sdk.js";
import { loadContext, TargetType } from "../context.js";
import type { ParsedArgs } from "../types.js";
import { InputValidationError } from "../utils/validators.js";
import { requireAmountOrAll, resolveMarketContext } from "./shared/context.js";
import { buildSdkErrorOutput } from "./shared/errors.js";
import { getRepayNoDebtError } from "./shared/market.js";
import { printJson, exitWithCode } from "./shared/output.js";
import { executeRepayTransaction } from "./repay/execute.js";
import { buildRepaySimulationPayload } from "./repay/simulate.js";
import type { RepayRuntime } from "./repay/types.js";

export async function cmdRepay(args: ParsedArgs): Promise<void> {
  const ctx = loadContext();
  let marketId: string | undefined;

  try {
    requireAmountOrAll(args.amount, args.repayAll, "--repay-all");
    const {
      marketId: resolvedMarketId,
      chain,
      walletAddress,
      walletTopic,
    } = resolveMarketContext(args, ctx, {
      supportedChains: SUPPORTED_CHAINS,
      requireWalletTopic: !args.simulate,
    });

    marketId = resolvedMarketId;
    const chainId = getChainId(chain);
    const runtime: RepayRuntime = {
      sdk: getSDK(),
      marketId: resolvedMarketId,
      chain,
      chainId,
      walletAddress,
      walletTopic,
      ...(await getMarketRuntimeData(chainId, resolvedMarketId, walletAddress)),
    };

    if (runtime.userData.borrowed.isZero()) {
      printJson(getRepayNoDebtError());
      exitWithCode(1);
    }

    if (args.simulate) {
      printJson(await buildRepaySimulationPayload(args, runtime));
      exitWithCode(0);
    }

    const result = await executeRepayTransaction(runtime, args);
    printJson(result.payload);
    exitWithCode(result.exitCode);
  } catch (err) {
    if (err instanceof InputValidationError) {
      printJson({
        status: "error",
        reason: err.message,
      });
      exitWithCode(1);
    }

    const message = (err as Error).message || String(err);
    printJson(
      buildSdkErrorOutput(message, {
        targetType: TargetType.Market,
        targetId: marketId,
        insufficientReason: "insufficient_balance",
        insufficientMessage: "Insufficient loan token balance in wallet to repay",
      })
    );
    exitWithCode(1);
  }
}

import type { Address } from "viem";
import { getSDK, getChainId, SUPPORTED_CHAINS } from "../../sdk.js";
import { setSelectedMarket, type SelectedMarket } from "../../context.js";
import { mapMarketUserPosition } from "../../utils/position.js";
import {
  isSupportedChain,
  isValidAddress,
  isValidMarketId,
} from "../../utils/validators.js";
import type { CommandResult } from "../shared/result.js";
import type { SelectArgs } from "./types.js";

const ZONE_SMART_LENDING = 3;
const TERM_TYPE_FIXED = 1;

export async function runSelectMarket(args: SelectArgs): Promise<CommandResult> {
  if (!args.walletTopic) {
    return { exitCode: 1, payload: { status: "error", reason: "--wallet-topic required" } };
  }
  if (!args.walletAddress) {
    return {
      exitCode: 1,
      payload: { status: "error", reason: "--wallet-address required" },
    };
  }
  if (!args.market) {
    return {
      exitCode: 1,
      payload: { status: "error", reason: "--market required" },
    };
  }

  const chain = args.chain || "eip155:56";
  if (!isSupportedChain(chain, SUPPORTED_CHAINS)) {
    return {
      exitCode: 1,
      payload: {
        status: "error",
        reason: `Unsupported chain: ${chain}. Supported: ${SUPPORTED_CHAINS.join(", ")}`,
      },
    };
  }
  if (!isValidMarketId(args.market)) {
    return {
      exitCode: 1,
      payload: {
        status: "error",
        reason: `Invalid market ID: ${args.market}`,
      },
    };
  }
  if (!isValidAddress(args.walletAddress)) {
    return {
      exitCode: 1,
      payload: {
        status: "error",
        reason: `Invalid wallet address: ${args.walletAddress}`,
      },
    };
  }

  const marketId = args.market as Address;
  const walletAddress = args.walletAddress as Address;
  const chainId = getChainId(chain);

  try {
    const sdk = getSDK();
    const marketInfo = await sdk.getMarketInfo(chainId, marketId);
    const marketZone = marketInfo.zone;
    const marketTermType = (marketInfo as { termType?: number }).termType;

    if (marketZone === ZONE_SMART_LENDING) {
      return {
        exitCode: 1,
        payload: {
          status: "error",
          reason: "unsupported_market_type",
          message: "SmartLending markets are not supported. Use regular markets only.",
        },
      };
    }

    if (marketTermType === TERM_TYPE_FIXED) {
      return {
        exitCode: 1,
        payload: {
          status: "error",
          reason: "unsupported_market_type",
          message: "Fixed-term markets are not supported. Use regular markets only.",
        },
      };
    }

    const userData = await sdk.getMarketUserData(chainId, marketId, walletAddress);
    const selectedMarket: SelectedMarket = {
      marketId,
      chain,
      collateralSymbol: userData.collateralInfo.symbol,
      loanSymbol: userData.loanInfo.symbol,
      zone: marketZone,
      termType: marketTermType,
    };

    const mappedPosition = mapMarketUserPosition(userData, {
      collateralPrice: 0,
      loanPrice: 0,
    });
    setSelectedMarket(selectedMarket, walletAddress, args.walletTopic);

    return {
      exitCode: 0,
      payload: {
        status: "success",
        action: "selected",
        market: selectedMarket,
        userAddress: walletAddress,
        position: {
          collateral: mappedPosition.collateral,
          borrowed: mappedPosition.borrowed,
          ltv: mappedPosition.ltv,
          lltv: mappedPosition.lltv,
          health: mappedPosition.health,
          loanable: userData.loanable?.toFixed(8) || "0",
          withdrawable: userData.withdrawable?.toFixed(8) || "0",
          walletCollateralBalance: mappedPosition.walletCollateralBalance,
          walletLoanBalance: mappedPosition.walletLoanBalance,
          hasPosition: mappedPosition.hasPosition,
        },
        message: mappedPosition.hasPosition
          ? `Selected ${selectedMarket.collateralSymbol}/${selectedMarket.loanSymbol} market. Collateral: ${mappedPosition.collateral}, Borrowed: ${mappedPosition.borrowed}`
          : `Selected ${selectedMarket.collateralSymbol}/${selectedMarket.loanSymbol} market. No existing position.`,
      },
    };
  } catch (err) {
    const message = (err as Error).message || String(err);
    if (message.includes("market not found") || message.includes("invalid")) {
      return {
        exitCode: 1,
        payload: {
          status: "error",
          reason: "invalid_market",
          message: `Market ${marketId} not found or invalid on ${chain}`,
        },
      };
    }

    return {
      exitCode: 1,
      payload: {
        status: "error",
        reason: "sdk_error",
        message,
      },
    };
  }
}

import { loadContext } from "../../context.js";

export function buildSelectShowPayload(): Record<string, unknown> {
  const ctx = loadContext();
  if (!ctx.selectedVault && !ctx.selectedMarket) {
