import type { Address } from "viem";
import { getChainId, getSDK, SUPPORTED_CHAINS } from "../../sdk.js";
import { setSelectedVault, type SelectedVault } from "../../context.js";
import { mapVaultUserPosition } from "../../utils/position.js";
import { isSupportedChain, isValidAddress } from "../../utils/validators.js";
import type { CommandResult } from "../shared/result.js";
import type { SelectArgs } from "./types.js";

export async function runSelectVault(args: SelectArgs): Promise<CommandResult> {
  if (!args.walletTopic) {
    return { exitCode: 1, payload: { status: "error", reason: "--wallet-topic required" } };
  }
  if (!args.walletAddress) {
    return {
      exitCode: 1,
      payload: { status: "error", reason: "--wallet-address required" },
    };
  }
  if (!args.vault) {
    return {
      exitCode: 1,
      payload: { status: "error", reason: "--vault required" },
    };
  }

  const chain = args.chain || "eip155:56";
  if (!isSupportedChain(chain, SUPPORTED_CHAINS)) {
    return {
      exitCode: 1,
      payload: {
        status: "error",
        reason: `Unsupported chain: ${chain}. Supported: ${SUPPORTED_CHAINS.join(", ")}`,
      },
    };
  }
  if (!isValidAddress(args.vault)) {
    return {
      exitCode: 1,
      payload: {
        status: "error",
        reason: `Invalid vault address: ${args.vault}`,
      },
    };
  }
  if (!isValidAddress(args.walletAddress)) {
    return {
      exitCode: 1,
      payload: {
        status: "error",
        reason: `Invalid wallet address: ${args.walletAddress}`,
      },
    };
  }

  const vaultAddress = args.vault as Address;
  const walletAddress = args.walletAddress as Address;
  const chainId = getChainId(chain);

  try {
    const sdk = getSDK();
    const vaultInfo = await sdk.getVaultInfo(chainId, vaultAddress);
    const userData = await sdk.getVaultUserData(
      chainId,
      vaultAddress,
      walletAddress,
      vaultInfo
    );

    const assetInfo = vaultInfo.assetInfo;
    const selectedVault: SelectedVault = {
      address: vaultAddress,
      name: `${assetInfo.symbol} Vault`,
      asset: {
        symbol: assetInfo.symbol,
        address: assetInfo.address,
        decimals: assetInfo.decimals,
      },
      chain,
    };

    const mappedPosition = mapVaultUserPosition(userData);
    setSelectedVault(
      selectedVault,
      walletAddress,
      args.walletTopic,
      mappedPosition.position
    );

    return {
      exitCode: 0,
      payload: {
        status: "success",
        action: "selected",
        vault: selectedVault,
        userAddress: walletAddress,
        balance: mappedPosition.walletBalance,
        vaultBalance: mappedPosition.position.assets,
        position: {
          assets: mappedPosition.position.assets,
          balance: mappedPosition.position.assets,
          walletBalance: mappedPosition.walletBalance,
          assetSymbol: assetInfo.symbol,
          hasPosition: mappedPosition.hasPosition,
        },
        message: mappedPosition.hasPosition
          ? `Selected ${selectedVault.name}. You have ${mappedPosition.position.assets} ${assetInfo.symbol} deposited. Wallet balance: ${mappedPosition.walletBalance} ${assetInfo.symbol}.`
          : `Selected ${selectedVault.name}. No existing position.`,
      },
    };
  } catch (err) {
    const message = (err as Error).message || String(err);
    if (message.includes("vault not found") || message.includes("invalid")) {
      return {
        exitCode: 1,
        payload: {
          status: "error",
          reason: "invalid_vault",
          message: `Vault ${vaultAddress} not found or invalid on ${chain}`,
        },
      };
    }

    return {
      exitCode: 1,
      payload: {
        status: "error",
        reason: "sdk_error",
        message,
      },
    };
  }
}

import { clearContext } from "../context.js";
import { printJson, exitWithCode } from "./shared/output.js";
import { runSelectMarket } from "./select/market.js";
import { buildSelectClearedPayload, buildSelectShowPayload } from "./select/show.js";
import type { SelectArgs } from "./select/types.js";
import { runSelectVault } from "./select/vault.js";

export type { SelectArgs };

export async function cmdSelect(args: SelectArgs): Promise<void> {
  if (args.clear) {
    clearContext();
    printJson(buildSelectClearedPayload());
    exitWithCode(0);
  }

  if (args.show) {
    printJson(buildSelectShowPayload());
    exitWithCode(0);
  }

  if (!args.vault && !args.market) {
    printJson({
      status: "error",
      reason: "--vault or --market required (or use --show to see current selection)",
    });
    exitWithCode(1);
  }

  if (args.vault && args.market) {
    printJson({
      status: "error",
      reason: "Cannot select both --vault and --market at the same time",
    });
    exitWithCode(1);
  }

  const result = args.market
    ? await runSelectMarket(args)
    : await runSelectVault(args);
  printJson(result.payload);
  exitWithCode(result.exitCode);
}

import type { Address } from "viem";
import type { LendingContext } from "../../context.js";
import type { ParsedArgs } from "../../types.js";
import {
  InputValidationError,
  isSupportedChain,
  isValidAddress,
  isValidMarketId,
} from "../../utils/validators.js";
import { inferLatestTopicByAddress } from "./wallet-session.js";

const DEFAULT_CHAIN = "eip155:56";

function requireAddress(
  value: string | null | undefined,
  missingMessage: string,
  invalidMessageFactory: (value: string) => string
): Address {
  if (!value) {
    throw new InputValidationError(missingMessage);
  }
  if (!isValidAddress(value)) {
    throw new InputValidationError(invalidMessageFactory(value));
  }
  return value;
}

function requireWalletTopic(value: string | null | undefined): string {
  if (!value) {
    throw new InputValidationError(
      "No wallet connected. Use 'select' or provide --wallet-topic"
    );
  }
  return value;
}

function requireMarketId(value: string | null | undefined): Address {
  if (!value) {
    throw new InputValidationError(
      "No market selected. Use 'select --market <id>' or provide --market"
    );
  }
  if (!isValidMarketId(value)) {
    throw new InputValidationError(`Invalid market ID: ${value}`);
  }
  return value as Address;
}

export function requireSupportedChain(
  chain: string,
  supportedChains: readonly string[]
): string {
  if (!isSupportedChain(chain, supportedChains)) {
    throw new InputValidationError(
      `Unsupported chain: ${chain}. Supported: ${supportedChains.join(", ")}`
    );
  }
  return chain;
}

export function requireAmount(value: string | undefined): string {
  if (!value) {
    throw new InputValidationError("--amount required");
  }
  return value;
}

export function requireAmountOrAll(
  amount: string | undefined,
  allFlag: boolean | undefined,
  allFlagName: "--withdraw-all" | "--repay-all"
): void {
  if (!amount && !allFlag) {
    throw new InputValidationError(`--amount or ${allFlagName} required`);
  }
  if (amount && allFlag) {
    throw new InputValidationError(
      `--amount and ${allFlagName} cannot be used together`
    );
  }
}

export interface ResolveOptions {
  supportedChains: readonly string[];
  requireWalletTopic?: boolean;
}

export interface ResolvedVaultContext {
  vaultAddress: Address;
  chain: string;
  walletAddress: Address;
  walletTopic: string | null;
}

export interface ResolvedMarketContext {
  marketId: Address;
  chain: string;
  walletAddress: Address;
  walletTopic: string | null;
}

export function resolveVaultContext(
  args: ParsedArgs,
  ctx: LendingContext,
  options: ResolveOptions
): ResolvedVaultContext {
  const vaultAddressInput = args.vault || ctx.selectedVault?.address;
  const chain = args.chain || ctx.selectedVault?.chain || DEFAULT_CHAIN;
  let walletTopicInput = args.walletTopic || null;
  const walletAddressInput = args.walletAddress || ctx.userAddress;

  if (args.walletAddress && !args.walletTopic) {
    const inferredTopic = inferLatestTopicByAddress(args.walletAddress);
    if (inferredTopic) {
      walletTopicInput = inferredTopic;
    } else if (options.requireWalletTopic !== false) {
      throw new InputValidationError(
        `No wallet session found for ${args.walletAddress}. Provide --wallet-topic or reconnect this wallet`
      );
    }
  } else if (!walletTopicInput) {
    walletTopicInput = ctx.walletTopic || null;
  }

  const vaultAddress = requireAddress(
    vaultAddressInput,
    "No vault selected. Use 'select --vault <address>' or provide --vault",
    (value) => `Invalid vault address: ${value}`
  );
  const walletAddress = requireAddress(
    walletAddressInput,
    "No wallet address. Use 'select' or provide --wallet-address",
    (value) => `Invalid wallet address: ${value}`
  );

  requireSupportedChain(chain, options.supportedChains);
  const walletTopic =
    options.requireWalletTopic === false
      ? walletTopicInput || null
      : requireWalletTopic(walletTopicInput);

  return {
    vaultAddress,
    chain,
    walletAddress,
    walletTopic,
  };
}

export function resolveMarketContext(
  args: ParsedArgs,
  ctx: LendingContext,
  options: ResolveOptions
): ResolvedMarketContext {
  const marketIdInput = args.market || ctx.selectedMarket?.marketId;
  const chain = args.chain || ctx.selectedMarket?.chain || DEFAULT_CHAIN;
  let walletTopicInput = args.walletTopic || null;
  const walletAddressInput = args.walletAddress || ctx.userAddress;

  if (args.walletAddress && !args.walletTopic) {
    const inferredTopic = inferLatestTopicByAddress(args.walletAddress);
    if (inferredTopic) {
      walletTopicInput = inferredTopic;
    } else if (options.requireWalletTopic !== false) {
      throw new InputValidationError(
        `No wallet session found for ${args.walletAddress}. Provide --wallet-topic or reconnect this wallet`
      );
    }
  } else if (!walletTopicInput) {
    walletTopicInput = ctx.walletTopic || null;
  }

  const validMarketId = requireMarketId(marketIdInput);
  const walletAddress = requireAddress(
    walletAddressInput,
    "No wallet address. Use 'select' or provide --wallet-address",
    (value) => `Invalid wallet address: ${value}`
  );

  requireSupportedChain(chain, options.supportedChains);
  const walletTopic =
    options.requireWalletTopic === false
      ? walletTopicInput || null
      : requireWalletTopic(walletTopicInput);

  return {
    marketId: validMarketId,
    chain,
    walletAddress,
    walletTopic,
  };
}

import { TargetType } from "../../context.js";

export interface SdkErrorMappingOptions {
  targetType: TargetType;
  targetId?: string;
  insufficientReason?: string;
  insufficientMessage?: string;
  insufficientKeywords?: string[];
}

const DEFAULT_INSUFFICIENT_KEYWORDS = ["insufficient", "exceeds", "balance"];

export function buildSdkErrorOutput(
  message: string,
  options: SdkErrorMappingOptions
): Record<string, unknown> {
  const targetLabel = options.targetType === TargetType.Vault ? "Vault" : "Market";
  const invalidPhrase =
    options.targetType === TargetType.Vault
      ? message.includes("vault not found") || message.includes("invalid vault")
      : message.includes("market not found") || message.includes("invalid market");

  if (invalidPhrase) {
    return {
      status: "error",
      reason:
        options.targetType === TargetType.Vault ? "invalid_vault" : "invalid_market",
      message: options.targetId
        ? `${targetLabel} ${options.targetId} not found or invalid`
        : `${targetLabel} not found or invalid`,
    };
  }

  const insufficientKeywords = options.insufficientKeywords || DEFAULT_INSUFFICIENT_KEYWORDS;
  const isInsufficient = insufficientKeywords.some((keyword) =>
    message.toLowerCase().includes(keyword.toLowerCase())
  );
  if (isInsufficient && options.insufficientReason && options.insufficientMessage) {
    return {
      status: "error",
      reason: options.insufficientReason,
      message: options.insufficientMessage,
    };
  }

  if (message.includes("RPC") || message.includes("fetch")) {
    return {
      status: "error",
      reason: "rpc_error",
      message,
      hint: "Try setting a custom RPC with: config --set-rpc --chain <chain> --url <url>",
    };
  }

  return {
    status: "error",
    reason: "sdk_error",
    message,
  };
}

import type { MarketUserData } from "../../types.js";
import type { MappedMarketPosition } from "../../utils/position.js";

export function buildMarketPositionPayload(
  mappedPosition: MappedMarketPosition,
  extras: Record<string, unknown> = {}
): Record<string, unknown> {
  return {
    collateral: mappedPosition.collateral,
    borrowed: mappedPosition.borrowed,
    ltv: mappedPosition.ltv,
    lltv: mappedPosition.lltv,
    health: mappedPosition.health,
    walletCollateralBalance: mappedPosition.walletCollateralBalance,
    walletLoanBalance: mappedPosition.walletLoanBalance,
    ...extras,
  };
}

export function buildRepayHint(userData: MarketUserData): string | undefined {
  if (userData.withdrawable?.gt(0) && userData.borrowed.isZero()) {
    return `Debt fully repaid. You can withdraw up to ${userData.withdrawable.toFixed(4)} ${userData.collateralInfo.symbol} collateral.`;
  }
  return undefined;
}

export function getRepayNoDebtError(): Record<string, unknown> {
  return {
    status: "error",
    reason: "no_debt",
    message: "No debt to repay in this market",
  };
}

export function getWithdrawNoCollateralError(): Record<string, unknown> {
  return {
    status: "error",
    reason: "no_collateral",
    message: "No collateral to withdraw from this market",
  };
}

export function getWithdrawAllHasDebtError(
  userData: MarketUserData
): Record<string, unknown> {
  return {
    status: "error",
    reason: "has_debt",
    message:
      "Cannot withdraw all collateral while you have outstanding debt. Repay debt first or use --amount.",
    debt: userData.borrowed.toFixed(8),
    withdrawable: userData.withdrawable.toFixed(8),
  };
}

export function getExceedsWithdrawableError(
  requestedAmount: string,
  userData: MarketUserData,
  collateralSymbol: string
): Record<string, unknown> {
  return {
    status: "error",
    reason: "exceeds_withdrawable",
    message: `Cannot withdraw ${requestedAmount} ${collateralSymbol}. Max withdrawable: ${userData.withdrawable.toFixed(4)} ${collateralSymbol}`,
    maxWithdrawable: userData.withdrawable.toFixed(8),
    hint: "Repay some debt to increase withdrawable amount",
  };
}

export function stringifyJson(payload: unknown): string {
  return JSON.stringify(payload);
}

export function printJson(payload: unknown): void {
  console.log(stringifyJson(payload));
}

export function printErrorJson(payload: unknown): void {
  console.error(stringifyJson(payload));
}

export function exitWithCode(code: number): never {
  process.exit(code);
}

export interface CommandResult {
  exitCode: 0 | 1;
  payload: Record<string, unknown>;
}

import type { StepParam } from "@lista-dao/moolah-lending-sdk";
import type { TxResult } from "../../types.js";
import { InputValidationError } from "../../utils/validators.js";

export function ensureStepsGenerated(steps: StepParam[]): StepParam[] {
  if (steps.length === 0) {
    throw new InputValidationError("No steps generated");
  }
  return steps;
}

export function buildExecutionFailureOutput(
  results: TxResult[],
  totalSteps: number
): Record<string, unknown> {
  const lastResult = results[results.length - 1];
  const completedSteps = countCompletedSentSteps(results);
  const output: Record<string, unknown> = {
    status: lastResult?.status || "error",
    reason: lastResult?.reason || "execution_failed",
    failedStep: lastResult?.step,
    completedSteps,
    totalSteps,
  };

  const successfulTxs = collectSuccessfulTxs(results);

  if (successfulTxs.length > 0) {
    output.completedTxs = successfulTxs;
  }

  return output;
}

export function buildPendingExecutionOutput(
  result: Extract<TxResult, { status: "pending" }>,
  results: TxResult[],
  totalSteps: number
): Record<string, unknown> {
  return {
    status: "pending",
    reason: result.reason || "tx_submitted_pending_confirmation",
    pendingStep: result.step,
    txHash: result.txHash,
    explorer: result.explorer,
    completedSteps: countCompletedSentSteps(results),
    totalSteps,
    message:
      "Transaction was submitted but confirmation is still pending. Please check explorer and avoid resubmitting the same action.",
  };
}

function countCompletedSentSteps(results: TxResult[]): number {
  return results.filter((r) => r.status === "sent").length;
}

function collectSuccessfulTxs(
  results: TxResult[]
): Array<{ step?: string; txHash: string }> {
  return results
    .filter((r): r is Extract<TxResult, { status: "sent" }> => r.status === "sent")
    .map((r) => ({ step: r.step, txHash: r.txHash }));
}

import { existsSync, readFileSync } from "fs";
import { homedir } from "os";
import { join } from "path";

const WALLET_SESSIONS_FILE = join(homedir(), ".agent-wallet", "sessions.json");

interface StoredWalletSession {
  accounts?: string[];
  createdAt?: string;
  updatedAt?: string;
}

function parseAccountAddress(account: string): string {
  return account.split(":").slice(2).join(":");
}

export function inferLatestTopicByAddress(address: string): string | null {
  if (!existsSync(WALLET_SESSIONS_FILE)) return null;

  try {
    const sessions = JSON.parse(
      readFileSync(WALLET_SESSIONS_FILE, "utf-8")
    ) as Record<string, StoredWalletSession>;

    const needle = address.toLowerCase();
    const matches = Object.entries(sessions)
      .filter(([, session]) =>
        (session.accounts || []).some(
          (account) => parseAccountAddress(account).toLowerCase() === needle
        )
      )
      .map(([topic, session]) => ({
        topic,
        sortKey: session.updatedAt || session.createdAt || "",
      }))
      .sort((a, b) => b.sortKey.localeCompare(a.sortKey));

    if (matches.length === 0) return null;
    return matches[0].topic;
  } catch {
    return null;
  }
}

/**
 * Market supply command
 * Supply collateral to a Lista Lending market
 * After success, shows updated position and max borrowable
 */

import { getSDK, getChainId, SUPPORTED_CHAINS } from "../sdk.js";
import { executeSteps } from "../executor.js";
import {
  loadContext,
  TargetType,
} from "../context.js";
import type { ParsedArgs } from "../types.js";
import { mapMarketUserPosition } from "../utils/position.js";
import { InputValidationError, parsePositiveUnits } from "../utils/validators.js";
import {
  requireAmount,
  resolveMarketContext,
} from "./shared/context.js";
import { printJson, exitWithCode } from "./shared/output.js";
import {
  buildExecutionFailureOutput,
  buildPendingExecutionOutput,
  ensureStepsGenerated,
} from "./shared/tx.js";
import { buildSdkErrorOutput } from "./shared/errors.js";
import { buildMarketPositionPayload } from "./shared/market.js";

export async function cmdSupply(args: ParsedArgs): Promise<void> {
  const ctx = loadContext();
  let operationContext:
    | {
        marketId: string;
        chain: string;
        amount: string;
      }
    | undefined;

  try {
    const amount = requireAmount(args.amount);
    const { marketId, chain, walletAddress, walletTopic } = resolveMarketContext(
      args,
      ctx,
      { supportedChains: SUPPORTED_CHAINS }
    );
    const chainId = getChainId(chain);
    const sdk = getSDK();

    // 1. Get market info for collateral decimals
    const marketInfo = await sdk.getWriteConfig(chainId, marketId);
    const collateralInfo = marketInfo.collateralInfo;
    const decimals = collateralInfo.decimals;

    // 2. Parse amount with correct decimals
    const assets = parsePositiveUnits(amount, decimals, "amount");
    operationContext = { marketId, chain, amount };
    // 3. Build supply steps (may include approve step)
    const steps = ensureStepsGenerated(
      await sdk.buildSupplyParams({
        chainId,
        marketId,
        assets,
        walletAddress,
        marketInfo,
      })
    );

    // 4. Execute steps via lista-wallet-connect
    const results = await executeSteps(steps, {
      topic: walletTopic!,
      chain,
    });

    // 5. Check result
    const lastResult = results[results.length - 1];

    if (lastResult.status === "pending") {
      printJson(buildPendingExecutionOutput(lastResult, results, steps.length));
      exitWithCode(0);
    }

    if (lastResult.status === "sent") {
      // 6. Re-query position on-chain after successful supply
      const userData = await sdk.getMarketUserData(chainId, marketId, walletAddress);
      const mappedPosition = mapMarketUserPosition(userData, {
        collateralPrice: 0,
        loanPrice: 0,
      });

      printJson({
        status: "success",
        market: marketId,
        chain,
        collateral: collateralInfo.symbol,
        supplied: amount,
        steps: results.length,
        txHash: lastResult.txHash,
        explorer: lastResult.explorer,
        position: buildMarketPositionPayload(mappedPosition, {
          loanable: userData.loanable?.toFixed(8) || "0",
        }),
        hint: userData.loanable?.gt(0)
          ? `You can now borrow up to ${userData.loanable.toFixed(4)} ${userData.loanInfo.symbol}`
          : undefined,
      });
      exitWithCode(0);
    }

    printJson(buildExecutionFailureOutput(results, steps.length));
    exitWithCode(1);
  } catch (err) {
    if (err instanceof InputValidationError) {
      printJson({
        status: "error",
        reason: err.message,
      });
      exitWithCode(1);
    }

    const message = (err as Error).message || String(err);

    printJson(
      buildSdkErrorOutput(message, {
        targetType: TargetType.Market,
        targetId: operationContext?.marketId,
      })
    );
    exitWithCode(1);
  }
}

/**
 * Vaults command - list all available vaults
 */

import { fetchVaults } from "../api.js";
import { SUPPORTED_CHAINS } from "../config.js";
import { setLastFilters } from "../context.js";
import { printJson } from "./shared/output.js";
import { formatVaultDisplay } from "../presenters/lending.js";
import type { ListOrder } from "../types/lista-api.js";
import {
  isPositiveInteger,
  isSupportedChain,
  isValidOrder,
} from "../utils/validators.js";

export interface VaultsArgs {
  chain?: string;
  page?: number;
  pageSize?: number;
  sort?: string;
  order?: ListOrder;
  zone?: string | number;
  keyword?: string;
  assets?: string[];
  curators?: string[];
}

export async function cmdVaults(args: VaultsArgs): Promise<void> {
  const chain = args.chain || "eip155:56";

  if (!isSupportedChain(chain, SUPPORTED_CHAINS)) {
    printJson({
      status: "error",
      reason: `Unsupported chain: ${chain}. Supported: ${SUPPORTED_CHAINS.join(", ")}`,
    });
    process.exit(1);
  }

  if (args.page !== undefined && !isPositiveInteger(args.page)) {
    printJson({
      status: "error",
      reason: "--page must be a positive integer",
    });
    process.exit(1);
  }

  if (
    args.pageSize !== undefined &&
    !isPositiveInteger(args.pageSize)
  ) {
    printJson({
      status: "error",
      reason: "--page-size must be a positive integer",
    });
    process.exit(1);
  }

  if (args.order && !isValidOrder(args.order)) {
    printJson({
      status: "error",
      reason: "--order must be asc or desc",
    });
    process.exit(1);
  }

  try {
    const vaults = await fetchVaults({
      chain,
      page: args.page,
      pageSize: args.pageSize,
      sort: args.sort,
      order: args.order,
      zone: args.zone,
      keyword: args.keyword,
      assets: args.assets,
      curators: args.curators,
    });

    setLastFilters({
      vaults: {
        chain,
        page: args.page || 1,
        pageSize: args.pageSize || 100,
        sort: args.sort,
        order: args.order,
        zone: args.zone,
        keyword: args.keyword,
        assets: args.assets,
        curators: args.curators,
        at: new Date().toISOString(),
      },
    });

    if (vaults.length === 0) {
      printJson({
        status: "success",
        chain,
        vaults: [],
        message: "No vaults found",
      });
      return;
    }

    // Output JSON for agent parsing
    printJson({
      status: "success",
      chain,
      count: vaults.length,
      filters: {
        page: args.page || 1,
        pageSize: args.pageSize || 100,
        sort: args.sort,
        order: args.order,
        zone: args.zone,
        keyword: args.keyword,
        assets: args.assets,
        curators: args.curators,
      },
      vaults: vaults.map((v, i) => ({
        index: i,
        address: v.address,
        name: v.name,
        asset: v.assetSymbol,
        assetAddress: v.asset,
        decimals: v.displayDecimal,
        tvl: v.depositsUsd,
        apy: v.apy,
        curator: v.curator,
        display: formatVaultDisplay(v, i),
      })),
    });
  } catch (err) {
    printJson({
      status: "error",
      reason: "sdk_error",
      message: (err as Error).message,
    });
    process.exit(1);
  }
}

/**
 * Vault withdraw command
 * Withdraws assets from a Lista Lending vault
 * After success, re-queries position on-chain
 */

import { getSDK, getChainId, SUPPORTED_CHAINS } from "../sdk.js";
import { executeSteps } from "../executor.js";
import {
  loadContext,
  TargetType,
  updatePosition,
  type UserPosition,
} from "../context.js";
import type { ParsedArgs } from "../types.js";
import { mapVaultUserPosition } from "../utils/position.js";
import { InputValidationError, parsePositiveUnits } from "../utils/validators.js";
import {
  requireAmountOrAll,
  resolveVaultContext,
} from "./shared/context.js";
import { printJson, exitWithCode } from "./shared/output.js";
import {
  buildExecutionFailureOutput,
  buildPendingExecutionOutput,
  ensureStepsGenerated,
} from "./shared/tx.js";
import { buildSdkErrorOutput } from "./shared/errors.js";

export async function cmdWithdraw(args: ParsedArgs): Promise<void> {
  const ctx = loadContext();
  let operationContext:
    | {
        vaultAddress: string;
        chain: string;
        amount: string;
      }
    | undefined;

  try {
    requireAmountOrAll(args.amount, args.withdrawAll, "--withdraw-all");
    const { vaultAddress, chain, walletAddress, walletTopic } = resolveVaultContext(
      args,
      ctx,
      { supportedChains: SUPPORTED_CHAINS }
    );
    const chainId = getChainId(chain);
    const sdk = getSDK();

    // 1. Get vault info
    const vaultInfo = await sdk.getVaultInfo(chainId, vaultAddress);

    // 2. Get user data (required for withdraw-all)
    const userData = await sdk.getVaultUserData(
      chainId,
      vaultAddress,
      walletAddress,
      vaultInfo
    );

    if (args.withdrawAll && (!userData.shares || userData.shares.isZero())) {
      printJson({
        status: "error",
        reason: "no_position",
        message: "No shares to withdraw from this vault",
      });
      exitWithCode(1);
    }

    // 3. Parse amount (SDK uses assetInfo)
    const assetInfo = vaultInfo.assetInfo;
    const decimals = assetInfo.decimals;
    let assets: bigint | undefined;

    if (args.amount) {
      assets = parsePositiveUnits(args.amount, decimals, "amount");
    }

    const operationAmount = args.amount || "all";
    operationContext = {
      vaultAddress,
      chain,
      amount: operationAmount,
    };

    // 4. Build withdraw steps
    const steps = ensureStepsGenerated(
      await sdk.buildVaultWithdrawParams({
        chainId,
        vaultAddress,
        assets,
        withdrawAll: args.withdrawAll,
        walletAddress,
        vaultInfo,
        userData,
      })
    );

    // 5. Execute steps via lista-wallet-connect
    const results = await executeSteps(steps, {
      topic: walletTopic!,
      chain,
    });

    // 6. Check result
    const lastResult = results[results.length - 1];

    if (lastResult.status === "pending") {
      printJson(buildPendingExecutionOutput(lastResult, results, steps.length));
      exitWithCode(0);
    }

    if (lastResult.status === "sent") {
      // 7. Re-query position on-chain after successful withdraw
      // Re-fetch vault info to get fresh state after withdraw
      const freshVaultInfo = await sdk.getVaultInfo(chainId, vaultAddress);
      const newUserData = await sdk.getVaultUserData(
        chainId,
        vaultAddress,
        walletAddress,
        freshVaultInfo
      );

      const mappedPosition = mapVaultUserPosition(newUserData);

      const newPosition: UserPosition = mappedPosition.position;

      // Update context if this is the selected vault
      if (ctx.selectedVault?.address === vaultAddress) {
        updatePosition(newPosition);
      }

      printJson({
        status: "success",
        vault: vaultAddress,
        chain,
        asset: assetInfo.symbol,
        withdrawn: operationAmount,
        txHash: lastResult.txHash,
        explorer: lastResult.explorer,
        balance: mappedPosition.walletBalance,
        vaultBalance: newPosition.assets,
        position: {
          balance: newPosition.assets,
          assets: newPosition.assets,
          walletBalance: mappedPosition.walletBalance,
          assetSymbol: assetInfo.symbol,
          remaining: newPosition.assets !== "0",
        },
      });
      exitWithCode(0);
    }

    printJson(buildExecutionFailureOutput(results, steps.length));
    exitWithCode(1);
  } catch (err) {
    if (err instanceof InputValidationError) {
      printJson({
        status: "error",
        reason: err.message,
      });
      exitWithCode(1);
    }

    const message = (err as Error).message || String(err);

    printJson(
      buildSdkErrorOutput(message, {
        targetType: TargetType.Vault,
        targetId: operationContext?.vaultAddress,
        insufficientReason: "insufficient_assets",
        insufficientMessage: "Withdrawal amount exceeds your vault balance",
        insufficientKeywords: ["insufficient", "exceeds balance"],
      })
    );
    exitWithCode(1);
  }
}

/**
 * Configuration storage for Lista Lending skill
 * Stores RPC URLs and other settings in ~/.agent-wallet/lending-config.json
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "fs";
import { homedir } from "os";
import { join } from "path";

const CONFIG_DIR = join(homedir(), ".agent-wallet");
const CONFIG_FILE = join(CONFIG_DIR, "lending-config.json");

// Default public RPC endpoints with fallbacks
export const DEFAULT_RPCS: Record<string, string[]> = {
  "eip155:56": [
    "https://bsc-dataseed.binance.org",
    "https://bsc-dataseed1.bnbchain.org",
    "https://bsc-dataseed2.bnbchain.org",
    "https://bsc-dataseed3.bnbchain.org",
    "https://bsc-rpc.publicnode.com",
    "https://bsc-dataseed1.binance.org",
  ],
  "eip155:1": [
    "https://eth.drpc.org",
    "https://mainnet.gateway.tenderly.co",
    "https://ethereum-rpc.publicnode.com",
    "https://cloudflare-eth.com",
    "https://eth.llamarpc.com",
  ],
};

// Chain ID mapping
export const CHAIN_IDS: Record<string, number> = {
  "eip155:56": 56,
  "eip155:1": 1,
};

export const SUPPORTED_CHAINS = ["eip155:56", "eip155:1"];

export interface LendingConfig {
  rpcUrls: Record<string, string>; // Custom RPC overrides
  defaultChain: string;
}

const DEFAULT_CONFIG: LendingConfig = {
  rpcUrls: {},
  defaultChain: "eip155:56",
};

/**
 * Ensure config directory exists
 */
function ensureConfigDir(): void {
  if (!existsSync(CONFIG_DIR)) {
    mkdirSync(CONFIG_DIR, { recursive: true });
  }
}

/**
 * Load config from disk
 */
export function loadConfig(): LendingConfig {
  try {
    if (existsSync(CONFIG_FILE)) {
      const data = readFileSync(CONFIG_FILE, "utf-8");
      const parsed = JSON.parse(data) as Partial<LendingConfig>;
      return {
        ...DEFAULT_CONFIG,
        ...parsed,
      };
    }
  } catch {
    // Ignore errors, return default
  }
  return { ...DEFAULT_CONFIG };
}

/**
 * Save config to disk
 */
export function saveConfig(config: LendingConfig): void {
  ensureConfigDir();
  writeFileSync(CONFIG_FILE, JSON.stringify(config, null, 2));
}

/**
 * Get RPC URL for a chain (custom override > default)
 */
export function getRpcUrl(chain: string): string {
  const candidates = getRpcUrls(chain);
  if (candidates.length > 0) {
    return candidates[0];
  }

  throw new Error(`No RPC URL configured for chain: ${chain}`);
}

/**
 * Get all RPC URLs for a chain (for fallback)
 */
export function getRpcUrls(chain: string): string[] {
  const config = loadConfig();
  const result: string[] = [];
  const seen = new Set<string>();

  const addUrl = (value: string | undefined): void => {
    if (!value) return;
    const normalized = value.trim();
    if (!normalized || seen.has(normalized)) return;
    seen.add(normalized);
    result.push(normalized);
  };

  // Custom override takes priority, but keep defaults as fallbacks.
  addUrl(config.rpcUrls[chain]);

  const defaults = DEFAULT_RPCS[chain] || [];
  for (const url of defaults) {
    addUrl(url);
  }

  return result;
}

/**
 * Set custom RPC URL for a chain
 */
export function setRpcUrl(chain: string, url: string): void {
  if (!SUPPORTED_CHAINS.includes(chain)) {
    throw new Error(
      `Unsupported chain: ${chain}. Supported: ${SUPPORTED_CHAINS.join(", ")}`
    );
  }

  const config = loadConfig();
  config.rpcUrls[chain] = url;
  saveConfig(config);
}

/**
 * Clear custom RPC URL (revert to default)
 */
export function clearRpcUrl(chain: string): void {
  const config = loadConfig();
  delete config.rpcUrls[chain];
  saveConfig(config);
}

/**
 * Get chain ID number from CAIP-2 format
 */
export function getChainId(chain: string): number {
  const chainId = CHAIN_IDS[chain];
  if (!chainId) {
    throw new Error(
      `Unknown chain: ${chain}. Supported: ${SUPPORTED_CHAINS.join(", ")}`
    );
  }
  return chainId;
}

/**
 * Check if using custom RPC (vs default public RPC)
 */
export function isUsingCustomRpc(chain: string): boolean {
  const config = loadConfig();
  return !!config.rpcUrls[chain];
}

/**
 * RPC configuration type
 */
export type RpcType = "public" | "custom";

/**
 * Get RPC type for a chain
 */
export function getRpcType(chain: string): RpcType {
  return isUsingCustomRpc(chain) ? "custom" : "public";
}

/**
 * Get optimized concurrency and timeout settings based on RPC type
 */
export interface RpcConfig {
  type: RpcType;
  vaultConcurrency: number;
  marketConcurrency: number;
  itemTimeout: number;
  totalBudget: number;
  retryCount: number;
  retryDelay: number;
}

export function getRpcConfig(chain: string): RpcConfig {
  const type = getRpcType(chain);

  if (type === "custom") {
    return {
      type: "custom",
      vaultConcurrency: 5,
      marketConcurrency: 3,
      itemTimeout: 8000,
      totalBudget: 35000,
      retryCount: 2,
      retryDelay: 500,
    };
  }

  // Public RPC: conservative settings to avoid rate limits
  return {
    type: "public",
    vaultConcurrency: 2,
    marketConcurrency: 1,
    itemTimeout: 12000,
    totalBudget: 70000,
    retryCount: 3,
    retryDelay: 800,
  };
}

/**
 * Context storage for Lista Lending skill
 * Stores selected position and user info for session continuity
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "fs";
import { homedir } from "os";
import { join } from "path";

const CONFIG_DIR = join(homedir(), ".agent-wallet");
const CONTEXT_FILE = join(CONFIG_DIR, "lending-context.json");
const CONTEXT_SCHEMA_VERSION = 2;

export interface SelectedVault {
  address: string;
  name: string;
  asset: {
    symbol: string;
    address: string;
    decimals: number;
  };
  chain: string;
}

export interface UserPosition {
  shares: string;
  assets: string;
  assetsUsd?: string;
}

export interface SelectedMarket {
  marketId: string;
  chain: string;
  collateralSymbol?: string;
  loanSymbol?: string;
  zone?: number;
  termType?: number;
}

export enum TargetType {
  Vault = "vault",
  Market = "market",
}

export interface LastFilters {
  vaults?: Record<string, unknown>;
  markets?: Record<string, unknown>;
  holdings?: Record<string, unknown>;
}

export interface LendingContext {
  schemaVersion: number;
  selectedVault: SelectedVault | null;
  selectedMarket: SelectedMarket | null;
  userAddress: string | null;
  walletTopic: string | null;
  userPosition: UserPosition | null;
  lastFilters: LastFilters | null;
  lastUpdated: string | null;
}

const DEFAULT_CONTEXT: LendingContext = {
  schemaVersion: CONTEXT_SCHEMA_VERSION,
  selectedVault: null,
  selectedMarket: null,
  userAddress: null,
  walletTopic: null,
  userPosition: null,
  lastFilters: null,
  lastUpdated: null,
};

/**
 * Ensure config directory exists
 */
function ensureConfigDir(): void {
  if (!existsSync(CONFIG_DIR)) {
    mkdirSync(CONFIG_DIR, { recursive: true });
  }
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isSelectedVault(value: unknown): value is SelectedVault {
  if (!isObject(value)) return false;
  if (typeof value.address !== "string") return false;
  if (typeof value.name !== "string") return false;
  if (typeof value.chain !== "string") return false;
  if (!isObject(value.asset)) return false;
  return (
    typeof value.asset.symbol === "string" &&
    typeof value.asset.address === "string" &&
    typeof value.asset.decimals === "number"
  );
}

function isSelectedMarket(value: unknown): value is SelectedMarket {
  if (!isObject(value)) return false;
  return (
    typeof value.marketId === "string" &&
    typeof value.chain === "string"
  );
}

function isUserPosition(value: unknown): value is UserPosition {
  if (!isObject(value)) return false;
  return (
    typeof value.shares === "string" &&
    typeof value.assets === "string"
  );
}

function isLastFilters(value: unknown): value is LastFilters {
  return isObject(value);
}

function migrateContext(raw: unknown): LendingContext {
  const base: LendingContext = { ...DEFAULT_CONTEXT };

  if (!isObject(raw)) {
    return base;
  }

  const old = raw as Record<string, unknown>;
  const selectedVault = isSelectedVault(old.selectedVault)
    ? old.selectedVault
    : null;
  const selectedMarket = isSelectedMarket(old.selectedMarket)
    ? old.selectedMarket
    : null;
  const userPosition = isUserPosition(old.userPosition)
    ? old.userPosition
    : null;
  const lastFilters = isLastFilters(old.lastFilters)
    ? old.lastFilters
    : null;

  return {
    schemaVersion: CONTEXT_SCHEMA_VERSION,
    selectedVault,
    selectedMarket,
    userAddress:
      typeof old.userAddress === "string" ? old.userAddress : base.userAddress,
    walletTopic:
      typeof old.walletTopic === "string" ? old.walletTopic : base.walletTopic,
    userPosition,
    lastFilters,
    lastUpdated:
      typeof old.lastUpdated === "string" ? old.lastUpdated : base.lastUpdated,
  };
}

/**
 * Load context from disk
 */
export function loadContext(): LendingContext {
  try {
    if (existsSync(CONTEXT_FILE)) {
      const data = readFileSync(CONTEXT_FILE, "utf-8");
      return migrateContext(JSON.parse(data));
    }
  } catch {
    // Ignore errors, return default
  }
  return { ...DEFAULT_CONTEXT };
}

/**
 * Save context to disk
 */
export function saveContext(context: LendingContext): void {
  ensureConfigDir();
  context.schemaVersion = CONTEXT_SCHEMA_VERSION;
  context.lastUpdated = new Date().toISOString();
  writeFileSync(CONTEXT_FILE, JSON.stringify(context, null, 2));
}

/**
 * Set selected vault
 */
export function setSelectedVault(
  vault: SelectedVault,
  userAddress: string,
  walletTopic: string,
  position?: UserPosition
): void {
  const context = loadContext();
  context.selectedVault = vault;
  context.selectedMarket = null;
  context.userAddress = userAddress;
  context.walletTopic = walletTopic;
  context.userPosition = position || null;
  saveContext(context);
}

/**
 * Set selected market
 */
export function setSelectedMarket(
  market: SelectedMarket,
  userAddress: string,
  walletTopic: string
): void {
  const context = loadContext();
  context.selectedMarket = market;
  context.selectedVault = null; // Clear vault when selecting market
  context.userPosition = null; // Clear vault position
  context.userAddress = userAddress;
  context.walletTopic = walletTopic;
  saveContext(context);
}

/**
 * Update user position for selected vault
 */
export function updatePosition(position: UserPosition): void {
  const context = loadContext();
  context.userPosition = position;
  saveContext(context);
}

/**
 * Persist latest user-facing filters for vaults/markets/holdings.
 */
export function setLastFilters(filters: LastFilters): void {
  const context = loadContext();
  context.lastFilters = {
    ...(context.lastFilters || {}),
    ...filters,
  };
  saveContext(context);
}

/**
 * Clear selection context.
 */
export function clearContext(): void {
  saveContext({ ...DEFAULT_CONTEXT });
}

