export interface MappedVaultPosition {
  position: UserPosition;
  shares: string;
  assets: string;
  walletBalance: string;
  hasPosition: boolean;
}

export interface MappedMarketPosition {
  collateral: string;
  collateralUsd: string;
  borrowed: string;
  borrowedUsd: string;
  ltv: string;
  lltv: string;
  health: string;
  liquidationPriceRate: string;
  borrowRate: string;
  walletCollateralBalance: string;
  walletLoanBalance: string;
  hasPosition: boolean;
  isWhitelisted: boolean;
}

export function mapVaultUserPosition(userData: VaultUserData): MappedVaultPosition {
  const shares = userData.shares?.toFixed(8) || "0";
  const assets = userData.locked?.toFixed(8) || "0";
  const walletBalance = userData.balance?.toFixed(8) || "0";

  return {
    position: {
      shares,
      assets,
    },
    shares,
    assets,
    walletBalance,
    hasPosition: Number.parseFloat(assets) > 0,
  };
}

export function mapMarketUserPosition(
  userData: MarketUserData,
  prices: {
    collateralPrice: string | number;
    loanPrice: string | number;
  }
): MappedMarketPosition {
  const collateralPrice = Decimal.parse(prices.collateralPrice || 0);
  const loanPrice = Decimal.parse(prices.loanPrice || 0);

  const collateral = userData.collateral?.toFixed(8) || "0";
  const borrowed = userData.borrowed?.toFixed(8) || "0";
  const collateralUsd = userData.collateral.mul(collateralPrice).toFixed(8);
  const borrowedUsd = userData.borrowed.mul(loanPrice).toFixed(8);

  // Align with lista-mono userLoansAtom: health = LLTV / LTV when LTV > 0, else 100.
  const healthValue = userData.LTV.gt(0)
    ? userData.LLTV.div(userData.LTV).roundDown(18)
    : Decimal.parse(100);

  return {
    collateral,
    collateralUsd,
    borrowed,
    borrowedUsd,
    ltv: userData.LTV.toFixed(8),
    lltv: userData.LLTV.toFixed(8),
    health: healthValue.toFixed(8),
    liquidationPriceRate: userData.liqPriceRate.toFixed(18),
    borrowRate: userData.borrowRate.toFixed(8),
    walletCollateralBalance: userData.balances.collateral?.toFixed(8) || "0",
    walletLoanBalance: userData.balances.loan?.toFixed(8) || "0",
    hasPosition:
      Number.parseFloat(collateral) > 0 || Number.parseFloat(borrowed) > 0,
    isWhitelisted: userData.isWhiteList,
  };
}

import type { StepParam } from "@lista-dao/moolah-lending-sdk";
import type { TxResult } from "../types.js";

interface WalletConnectResponse {
  status?: string;
  txHash?: string;
  error?: string;
  reason?: string;
  revertReason?: string;
}

interface ExecSyncErrorLike {
  message?: string;
  stdout?: string | Buffer;
  stderr?: string | Buffer;
  output?: Array<string | Buffer | null | undefined>;
}

function toText(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (value instanceof Buffer) return value.toString("utf-8");
  return String(value);
}

function parseJsonLines(text: string): WalletConnectResponse[] {
  const responses: WalletConnectResponse[] = [];
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (!line.startsWith("{") || !line.endsWith("}")) continue;
    try {
      responses.push(JSON.parse(line) as WalletConnectResponse);
    } catch {
      // Ignore non-JSON lines.
    }
  }
  return responses;
}

function extractWalletConnectResponses(err: unknown): WalletConnectResponse[] {
  const e = err as ExecSyncErrorLike;
  const chunks = [
    toText(e.stdout),
    toText(e.stderr),
    ...(Array.isArray(e.output) ? e.output.map((item) => toText(item)) : []),
  ].filter(Boolean);

  const responses: WalletConnectResponse[] = [];
  for (const chunk of chunks) {
    responses.push(...parseJsonLines(chunk));
  }
  return responses;
}

function extractRevertReason(value: string): string {
  const normalize = (reason: string): string => {
    const cleaned = reason.replace(/\.$/, "").trim();
    const hexSuffix = cleaned.match(/^(.*?):\s*0x[0-9a-fA-F]+$/);
    if (hexSuffix?.[1]) {
      return hexSuffix[1].trim();
    }
    return cleaned;
  };

  const withReasonMatch = value.match(/with reason:\s*([^\n]+)/i);
  if (withReasonMatch?.[1]) {
    return normalize(withReasonMatch[1]);
  }
  const revertedMatch = value.match(/execution reverted:?\s*([^\n]+)/i);
  if (revertedMatch?.[1]) {
    return normalize(revertedMatch[1]);
  }
  return normalize(value);
}

export function mapWalletConnectResponse(
  response: WalletConnectResponse,
  step: StepParam["step"],
  explorerUrl?: string
): TxResult {
  if (response.status === "sent") {
    if (!response.txHash) {
      return {
        status: "error",
        reason: "wallet_connect_missing_tx_hash",
        step,
      };
    }
    return {
      status: "sent",
      txHash: response.txHash,
      explorer: explorerUrl,
      step,
    };
  }

  if (response.status === "rejected") {
    return {
      status: "rejected",
      reason: "user_rejected",
      step,
    };
  }

  return {
    status: "error",
    reason: response.error || "Unknown error",
    step,
  };
}

export function mapExecutionError(
  err: unknown,
  step: StepParam["step"]
): TxResult {
  const responses = extractWalletConnectResponses(err);
  const simulationFailed = responses.find((r) => r.status === "simulation_failed");
  if (simulationFailed) {
    const rawReason =
      simulationFailed.revertReason ||
      simulationFailed.error ||
      simulationFailed.reason ||
      "Transaction simulation failed";
    return {
      status: "reverted",
      reason: extractRevertReason(rawReason),
      step,
    };
  }

  const rejected = responses.find((r) => r.status === "rejected");
  if (rejected) {
    return {
      status: "rejected",
      reason: "user_rejected",
      step,
    };
  }

  const message = (err as Error)?.message || String(err);

  // Check for user rejection
  if (message.includes("User rejected") || message.includes("rejected")) {
    return {
      status: "rejected",
      reason: "user_rejected",
      step,
    };
  }

  // Check for contract revert
  if (message.includes("revert") || message.includes("execution reverted")) {
    const revertMatch = message.match(/reason="([^"]+)"/);
    return {
      status: "reverted",
      reason: revertMatch ? revertMatch[1] : "Contract execution reverted",
      step,
    };
  }

  // Check for insufficient funds
  if (message.includes("insufficient funds")) {
    return {
      status: "error",
      reason: "insufficient_balance",
      step,
    };
  }

  return {
    status: "error",
    reason: message,
    step,
  };
}

import type { Address } from "viem";
import { isAddress, parseUnits } from "viem";

export class InputValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "InputValidationError";
  }
}

export function isSupportedChain(
  chain: string,
  supportedChains: readonly string[]
): boolean {
  return supportedChains.includes(chain);
}

export function isPositiveInteger(value: number | undefined): boolean {
  return value !== undefined && Number.isInteger(value) && value > 0;
}

export function isValidOrder(value: string): value is "asc" | "desc" {
  return value === "asc" || value === "desc";
}

export function isValidAddress(value: string): value is Address {
  return isAddress(value);
}

export function isValidMarketId(value: string): boolean {
  if (isAddress(value)) return true;
  return /^0x[a-fA-F0-9]{64}$/.test(value);
}

export function parsePositiveUnits(
  value: string,
  decimals: number,
  fieldName: string
): bigint {
  try {
    const parsed = parseUnits(value, decimals);
    if (parsed <= 0n) {
      throw new InputValidationError(`--${fieldName} must be a positive number`);
    }
    return parsed;
  } catch (err) {
    if (err instanceof InputValidationError) throw err;
    throw new InputValidationError(`--${fieldName} must be a valid positive number`);
  }
}

export function normalizeHoldingChain(chain: string): string {
  const normalized = chain.trim().toLowerCase();
  if (normalized === "bsc") return "eip155:56";
  if (normalized === "ethereum" || normalized === "eth") return "eip155:1";
  throw new InputValidationError(`Unsupported holdings chain from API: ${chain}`);
}
